/* Mikronährstoffe für den Medizin-Atlas. Referenzwerte: D-A-CH (DGE), obere Grenzen: EFSA; jede Zahl mit Quelle (Feld quelle). */
window.MEDNUT = [{"id":"vitamin_a","name":"Vitamin A (Retinol)","gruppe":"Fettlösliche Vitamine","aktiveForm":"11-cis-Retinal (Sehvorgang), all-trans-Retinsäure (Genregulation über RAR/RXR); Speicherform Retinylester","funktion":"11-cis-Retinal bildet mit Opsin das Rhodopsin; Lichtabsorption isomerisiert es zu all-trans-Retinal und startet die Phototransduktion. All-trans-Retinsäure ist Ligand der nukleären Rezeptoren RAR/RXR und steuert Zelldifferenzierung von Epithelien und Immunzellen sowie die Embryogenese (Grundlage der Teratogenität).","aufnahme":"Retinylester werden im Lumen hydrolysiert, Retinol mizellär aufgenommen, in der Enterozyte durch LRAT reverestert und in Chylomikronen zur Leber gebracht; β-Carotin wird durch BCO1 gespalten, wobei ISX die Spaltung bei gutem Status herunterreguliert. Speicherung als Retinylester in hepatischen Sternzellen, Freisetzung als Retinol–RBP4–Transthyretin-Komplex.","mangel":"Früh: Nachtblindheit (verzögerte Rhodopsinregeneration), Xerosis conjunctivae, Bitot-Flecken, follikuläre Hyperkeratose. Spät: Keratomalazie mit Erblindung sowie erhöhte Infekt- und Masernletalität, v. a. bei Kindern in Ländern mit niedrigem Einkommen.","risiko":"Fettmalabsorption (Cholestase, exokrine Pankreasinsuffizienz, Mukoviszidose, Morbus Crohn, Zöliakie, bariatrische OP), Leberzirrhose, Alkohol, Protein- und Zinkmangel (verminderte RBP-Synthese). Orlistat, Colestyramin und Paraffinöl senken die Aufnahme.","ueberdosis":"Toxisch ist nur vorgeformtes Retinol (β-Carotin verursacht lediglich harmlose Carotinodermie): akut Hirndruckzeichen bis Pseudotumor cerebri, chronisch Hepatotoxizität durch Sternzellaktivierung und Fibrose, Knochenschmerzen; teratogen, daher Leber im ersten Trimester meiden. β-Carotin-Supplemente erhöhten bei Rauchern das Lungenkrebsrisiko (ATBC-, CARET-Studie).","quellen":"Retinol: Leber und Leberwurst (sehr hoch), Fisch, Eier, Käse, Butter; Provitamin A: Karotten, Süßkartoffel, Kürbis, Paprika, Aprikosen, grünes Blattgemüse. Die Carotinoid-Bioverfügbarkeit ist gering und matrixabhängig und steigt mit Fett und Zerkleinern/Erhitzen (DGE: 1 µg RAE = 1 µg Retinol = 12 µg β-Carotin).","labor":"Serum-Retinol ist homöostatisch reguliert und fällt erst bei weitgehend erschöpften Leberspeichern. Es sinkt zusätzlich in der Akutphase (RBP ist ein negatives Akute-Phase-Protein) sowie bei Protein-, Zinkmangel und Leberinsuffizienz, daher CRP mitbestimmen; Referenzmethoden für die Leberspeicher (Isotopenverdünnung) sind klinisch kaum verfügbar.","interaktion":"Zink ist für RBP-Synthese und Retinol-Dehydrogenase nötig; Vitamin-A-Mangel beeinträchtigt die Eisenmobilisation (Anämie trotz Speichereisen). Isotretinoin/Acitretin plus Vitamin-A-Supplemente wirken additiv toxisch; Alkohol verstärkt hepatische Depletion und Toxizität.","ref":{"wert":"m 850 / w 700 µg Retinolaktivitätsäquivalente/Tag (19 bis <65 J.); m 800 / w 700 µg (ab 65 J.)","art":"Empfehlung","quelle":"https://www.dge.de/wissenschaft/referenzwerte/vitamin-a/","stand":"2020"},"ul":{"wert":"3000 µg RE/Tag (nur vorgeformtes Vitamin A: Retinol und Retinylester)","art":"UL","quelle":"https://www.efsa.europa.eu/sites/default/files/2024-05/ul-summary-report.pdf (EFSA: Overview on Tolerable Upper Intake Levels, Version 11 (August 2025); Grundlage: EFSA NDA Panel 2024)"},"links":{"dis":["vitamin_a_mangel","xerophthalmie","malassimilation","exokrine_pankreasinsuffizienz","mukoviszidose","leberzirrhose","idiopathische_intrakranielle_hypertension","zinkmangel"],"path":["lipoproteine"]},"mcq":[{"q":"Ein Patient mit Leberzirrhose und Malnutrition hat ein erniedrigtes Serum-Retinol bei hohem CRP. Welche Aussage trifft am ehesten zu?","a":"Der Wert ist eingeschränkt verwertbar, da RBP-Synthese und Akute-Phase-Reaktion ihn senken","w":["Der Wert beweist sicher leere Leberspeicher, da Serum-Retinol linear mit den Speichern abfällt","Der Wert ist falsch hoch, da Retinol in der Akutphase aus Sternzellen freigesetzt wird","Der Wert ist zuverlässig, da Retinol unabhängig von RBP frei im Plasma zirkuliert"],"why":"Retinol zirkuliert an RBP4 gebunden; RBP ist negatives Akute-Phase-Protein und wird bei Leberinsuffizienz, Protein- und Zinkmangel vermindert gebildet."},{"q":"Warum ist hochdosiertes β-Carotin im Gegensatz zu Retinol praktisch nicht hepatotoxisch?","a":"Die BCO1-Spaltung zu Retinal wird bei gutem Vitamin-A-Status über ISX herunterreguliert","w":["β-Carotin wird praktisch nicht resorbiert, sondern nahezu vollständig mit dem Stuhl ausgeschieden","β-Carotin hemmt die Retinylester-Speicherung in den hepatischen Sternzellen","β-Carotin wird ausschließlich im Kolon durch Bakterien zu Retinol gespalten"],"why":"Retinsäure induziert den Repressor ISX, der BCO1 und den Carotinoid-Aufnahmetransporter SR-BI hemmt; überschüssiges β-Carotin lagert sich nur im Gewebe ab (Carotinodermie)."},{"q":"Ein Kind sieht in der Dämmerung schlecht, die Bindehaut zeigt schaumige, dreieckige Flecken. Welcher Mechanismus erklärt das Frühsymptom?","a":"Verzögerte Rhodopsinregeneration in den Stäbchen mangels 11-cis-Retinal","w":["Gestörte Retinsäure-Signalgebung in den Zapfen der Fovea centralis","Fehlende Kollagenquervernetzung in den Gefäßen der Bindehaut","Oxidative Schädigung des Linsenepithels durch freie Radikale"],"why":"Skotopisches Sehen hängt vom Rhodopsin der Stäbchen ab; die Bitot-Flecken zeigen zusätzlich die gestörte retinsäureabhängige Epitheldifferenzierung (Verhornung)."}]},{"id":"vitamin_d","name":"Vitamin D (Calciferole)","gruppe":"Fettlösliche Vitamine","aktiveForm":"1,25-Dihydroxycholecalciferol (Calcitriol); Speicher- und Transportform 25-Hydroxyvitamin D (Calcidiol)","funktion":"Calcitriol bindet den nukleären Vitamin-D-Rezeptor (VDR/RXR) und induziert u. a. TRPV6, Calbindin-D9k und PMCA1b für die intestinale Calciumaufnahme; es steigert die Phosphatabsorption, wirkt mit PTH auf Knochenumbau (RANKL) und renale Calciumrückresorption und hemmt die PTH-Transkription. Extraskelettale VDR-Wirkungen (Immunsystem, Muskel) sind belegt, ein präventiver Nutzen von Supplementen jenseits des Mangelausgleichs aber weitgehend nicht.","aufnahme":"In der Haut entsteht durch UVB aus 7-Dehydrocholesterol Prävitamin D3, das thermisch zu D3 isomerisiert; Nahrungsvitamin D wird mizellär aufgenommen und in Chylomikronen transportiert. Hydroxylierung in der Leber (v. a. CYP2R1) zu 25-OH-D und in der Niere durch CYP27B1 (durch PTH stimuliert, durch FGF23 und Phosphat gehemmt) zu Calcitriol; Abbau durch CYP24A1, Transport an Vitamin-D-bindendem Protein, Speicherung in Fett- und Muskelgewebe.","mangel":"Kinder: Rachitis (Kraniotabes, rachitischer Rosenkranz, Beinachsenfehlstellung, hypokalzämische Krämpfe). Erwachsene: Osteomalazie mit diffusen Knochenschmerzen, proximaler Muskelschwäche und Looser-Umbauzonen; biochemisch früh sekundärer Hyperparathyreoidismus, AP ↑, Phosphat ↓.","risiko":"Fehlende UVB-Exposition (Winterhalbjahr, Verhüllung), höheres Alter (geringere Hautsynthese), immobile Pflegeheimbewohner, dunkle Haut, Säuglinge (DGE), Adipositas (Sequestration im Fettgewebe), Fettmalabsorption, Niereninsuffizienz (Calcitriolmangel). Enzyminduktoren (Carbamazepin, Phenytoin, Phenobarbital, Rifampicin) und Glukokortikoide beschleunigen den Abbau.","ueberdosis":"Intoxikation praktisch nur durch Supplemente: Hyperkalzämie mit Polyurie, Erbrechen, Nephrokalzinose und Herzrhythmusstörungen; Sonnenlicht ist selbstlimitierend. Hohe Einzeldosen im Abstand von Tagen bis Wochen bergen laut BfR (2025) gesundheitliche Risiken (in Studien u. a. mehr Stürze und Frakturen). Calcitriol-vermittelte Hyperkalzämie auch bei Granulomatosen (Sarkoidose) und CYP24A1-Defekten.","quellen":"Hauptquelle ist die endogene Synthese; die übliche Ernährung liefert laut DGE nur 2–4 µg/Tag bei Erwachsenen. Nennenswert: fetter Seefisch (Hering, Lachs, Makrele), Lebertran, Eigelb, UV-exponierte Speisepilze (Vitamin D2).","labor":"Statusmarker ist 25-OH-D im Serum (Halbwertszeit etwa 2–3 Wochen); DGE-Zielwert ≥ 50 nmol/l (1 ng/ml ≈ 2,5 nmol/l). Calcitriol ist ungeeignet, da es bei Mangel durch sekundären Hyperparathyreoidismus normal oder erhöht sein kann; Immunoassays streuen erheblich (Standardisierung, Erfassung von D2 und 3-epi-25-OH-D).","interaktion":"Vitamin D steigert die Calcium- und Phosphataufnahme; mit Thiaziden (verminderte Calciurie) steigt das Hyperkalzämierisiko, und Hyperkalzämie potenziert die Digitalistoxizität. Enzyminduktoren, Glukokortikoide, Orlistat und Colestyramin senken den Status; Magnesiummangel beeinträchtigt PTH-Sekretion und -Wirkung und damit die renale Calcitriolbildung.","ref":{"wert":"20 µg/Tag (= 800 IE) bei fehlender endogener Synthese (Erwachsene, m und w)","art":"Schätzwert","quelle":"https://www.dge.de/wissenschaft/referenzwerte/vitamin-d/","stand":"2012"},"ul":{"wert":"100 µg/Tag (= 4000 IE)","art":"UL","quelle":"https://www.efsa.europa.eu/sites/default/files/2024-05/ul-summary-report.pdf (EFSA: Overview on Tolerable Upper Intake Levels, Version 11 (August 2025); Grundlage: EFSA NDA Panel 2018, 2023)"},"links":{"dis":["vitamin_d_mangel","vitamin_d_intoxikation","rachitis","osteomalazie","osteoporose","sekundaerer_hyperparathyreoidismus","hypokalzaemie","hyperkalzaemie","sarkoidose","chronische_nierenkrankheit","adipositas"],"path":["vitamin-d"]},"mcq":[{"q":"Bei Verdacht auf Osteomalazie ist Calcitriol normal, 25-OH-D deutlich erniedrigt und PTH erhöht. Wie ist das zu deuten?","a":"Vitamin-D-Mangel; der sekundäre Hyperparathyreoidismus hält Calcitriol über CYP27B1 aufrecht","w":["Ausreichender Vitamin-D-Status, da die aktive Form im Referenzbereich liegt","Primärer Hyperparathyreoidismus mit autonomer Calcitriol-Überproduktion der Niere","Messartefakt, da 25-OH-D und Calcitriol physiologisch stets streng gleichsinnig schwanken müssen"],"why":"PTH stimuliert die renale 1α-Hydroxylase, sodass Calcitriol trotz leerer Speicher normal bleibt; der Status wird deshalb über 25-OH-D beurteilt."},{"q":"Ein Patient mit Sarkoidose entwickelt unter einem Vitamin-D-Präparat eine Hyperkalzämie mit supprimiertem PTH. Welcher Mechanismus ist ursächlich?","a":"Ungeregelte extrarenale 1α-Hydroxylierung in Granulom-Makrophagen","w":["Gesteigerte PTH-Sekretion durch Granulominfiltration der Nebenschilddrüsen","Gesteigerte CYP24A1-Aktivität mit Anstau von 25-OH-D in der Niere","Vermehrte Hautsynthese von Vitamin D3 durch entzündliche Hyperämie"],"why":"Makrophagen exprimieren CYP27B1, das nicht durch PTH, Calcium oder FGF23 gegenreguliert wird – PTH-unabhängige, calcitriolvermittelte Hyperkalzämie."},{"q":"Warum führt intensive Sonnenexposition nicht zur Vitamin-D-Intoxikation?","a":"Überschüssiges Prävitamin D3 wird durch UVB zu inaktiven Photoprodukten isomerisiert","w":["Die hepatische 25-Hydroxylase wird bei hohen D3-Spiegeln durch Produkthemmung vollständig blockiert","Die Hautsynthese von 7-Dehydrocholesterol endet bei Sättigung des DBP","Melanin wird proportional zur Synthese gebildet und blockiert UVB komplett"],"why":"Bei anhaltender UVB-Exposition entstehen aus Prävitamin D3 Lumisterol und Tachysterol; die hepatische 25-Hydroxylierung ist dagegen kaum reguliert."}]},{"id":"vitamin_e","name":"Vitamin E (α-Tocopherol)","gruppe":"Fettlösliche Vitamine","aktiveForm":"RRR-α-Tocopherol (bzw. die 2R-Stereoisomere aus synthetischem all-rac-α-Tocopherol)","funktion":"Kettenbrechendes lipophiles Antioxidans in Membranen und Lipoproteinen: fängt Lipidperoxylradikale ab und unterbricht die Lipidperoxidation mehrfach ungesättigter Fettsäuren. Das entstehende Tocopheroxylradikal wird u. a. durch Ascorbat regeneriert; der Bedarf steigt mit der PUFA-Zufuhr.","aufnahme":"Mizellare Aufnahme (Gallensäuren und Lipase erforderlich), Transport in Chylomikronen. In der Leber selektiert das α-Tocopherol-Transferprotein (α-TTP) α-Tocopherol für den Einbau in VLDL, andere Formen (γ-Tocopherol, Tocotrienole) werden über CYP4F2-ω-Hydroxylierung zu CEHC abgebaut; Speicherung v. a. im Fettgewebe.","mangel":"Selten, meist bei schwerer Fettmalabsorption oder genetischem α-TTP-Defekt (AVED): spinozerebelläre Ataxie, Hinterstrangstörung, Areflexie, periphere Neuropathie, Pigmentretinopathie, Myopathie. Bei Frühgeborenen hämolytische Anämie; beim Erwachsenen entwickeln sich neurologische Zeichen über Jahre.","risiko":"Cholestatische Lebererkrankungen (PBC, Gallengangsatresie), Mukoviszidose, exokrine Pankreasinsuffizienz, Kurzdarm, Abetalipoproteinämie (MTTP), AVED (TTPA-Mutation), Frühgeborene. Orlistat und Colestyramin vermindern die Aufnahme.","ueberdosis":"Über Lebensmittel nicht erreichbar; hohe Supplementdosen hemmen die Thrombozytenaggregation und antagonisieren Vitamin K – Blutungsrisiko ist der kritische Effekt des EFSA-UL. In der SELECT-Studie war die Prostatakarzinominzidenz unter Vitamin E erhöht.","quellen":"Pflanzenöle (Weizenkeim-, Sonnenblumen-, Rapsöl) und daraus hergestellte Streichfette, Nüsse und Samen, Weizenkeime; tierische Lebensmittel enthalten wenig. Synthetisches all-rac-α-Tocopherol hat nur etwa die halbe Wirksamkeit (DGE: 1 mg RRR = 2 mg all-rac-α-Tocopherol).","labor":"Plasma-α-Tocopherol korreliert eng mit den Gesamtlipiden und wird deshalb auf Cholesterin bzw. Gesamtlipide bezogen. Bei Hyperlipidämie kann ein Mangel maskiert, bei Hypolipidämie (Abetalipoproteinämie, Malnutrition) vorgetäuscht werden.","interaktion":"Vitamin C regeneriert Tocopherol, Selen (Glutathionperoxidasen) wirkt synergistisch; hohe PUFA-Zufuhr erhöht den Bedarf. Hohe Dosen verstärken Vitamin-K-Antagonisten und Thrombozytenaggregationshemmer; Orlistat und Colestyramin senken die Absorption.","ref":{"wert":"8 mg RRR-α-Tocopherol/Tag (Erwachsene, m und w; 1 mg RRR = 2 mg all-rac)","art":"Schätzwert","quelle":"https://www.dge.de/wissenschaft/referenzwerte/vitamin-e/","stand":"2024"},"ul":{"wert":"300 mg α-Tocopherol/Tag (inkl. Schwangere und Stillende)","art":"UL","quelle":"https://www.efsa.europa.eu/sites/default/files/2024-05/ul-summary-report.pdf (EFSA: Overview on Tolerable Upper Intake Levels, Version 11 (August 2025); Grundlage: SCF 2003); bestätigt durch EFSA NDA Panel 2024: https://pubmed.ncbi.nlm.nih.gov/39099617/"},"links":{"dis":["malassimilation","mukoviszidose","exokrine_pankreasinsuffizienz","pbc","gallengangsatresie","friedreich_ataxie"],"path":["lipoproteine"]},"mcq":[{"q":"Ein 14-Jähriger hat progrediente Gangataxie, Areflexie und gestörte Tiefensensibilität ohne Kardiomyopathie und ohne Fettmalabsorption. Welcher Befund spricht für AVED statt Friedreich-Ataxie?","a":"Stark erniedrigtes Plasma-α-Tocopherol bei normalen Lipiden","w":["Homozygote GAA-Repeat-Expansion im FXN-Gen","Erhöhtes Plasma-α-Tocopherol bei verminderter Ausscheidung","Normales α-Tocopherol mit erhöhter Methylmalonsäure"],"why":"Bei AVED fehlt der α-TTP-vermittelte Einbau in VLDL; das friedreichähnliche Bild ist durch Vitamin E behandelbar und muss daher gezielt ausgeschlossen werden."},{"q":"Bei ausgeprägter Hypercholesterinämie liegt Plasma-α-Tocopherol im Referenzbereich. Was ist die korrekte Interpretation?","a":"Aussagekräftig erst nach Bezug auf Cholesterin bzw. Gesamtlipide","w":["Mangel sicher ausgeschlossen, da Tocopherol lipidunabhängig zirkuliert","Wert falsch niedrig, da LDL das Tocopherol oxidativ abbaut","Wert spiegelt direkt den Speicher im Fettgewebe wider"],"why":"Tocopherol wird in Lipoproteinen transportiert; hohe Lipide erhöhen den Absolutwert und können einen relativen Mangel verdecken."},{"q":"Warum ist γ-Tocopherol trotz hoher Zufuhr (z. B. Soja-, Maisöl) im Plasma viel niedriger als α-Tocopherol?","a":"Hepatisches α-TTP bevorzugt α-Tocopherol, γ-Tocopherol wird über CYP4F2 abgebaut","w":["γ-Tocopherol wird im Darm nicht mizellär gelöst und kaum resorbiert","γ-Tocopherol wird bereits in der Enterozyte nahezu vollständig zu α-Tocopherol methyliert","γ-Tocopherol wird an RBP4 gebunden und rasch renal eliminiert"],"why":"Die Diskriminierung erfolgt nicht bei der Absorption, sondern in der Leber durch α-TTP-Selektion und ω-Hydroxylierung der übrigen Formen."}]},{"id":"vitamin_k","name":"Vitamin K (Phyllochinon, Menachinone)","gruppe":"Fettlösliche Vitamine","aktiveForm":"Vitamin-K-Hydrochinon (KH₂) als Kofaktor der γ-Glutamylcarboxylase; K1 = Phyllochinon, K2 = Menachinone (MK-n)","funktion":"Kofaktor der γ-Glutamylcarboxylase, die Glutamat- in γ-Carboxyglutamatreste (Gla) der Gerinnungsfaktoren II, VII, IX, X, der Proteine C, S und Z sowie von Osteocalcin und Matrix-Gla-Protein umwandelt; Gla-Reste vermitteln die calciumabhängige Phospholipidbindung. Das dabei entstehende Vitamin-K-Epoxid wird durch VKORC1 recycelt – Angriffspunkt der Cumarine.","aufnahme":"Mizellar, gallensäure- und fettabhängig; Transport in Chylomikronen, K1 reichert sich v. a. in der Leber an, langkettige Menachinone zirkulieren länger (LDL) und erreichen extrahepatische Gewebe. Kleiner Körperpool mit raschem Umsatz, effizientes Recycling im Vitamin-K-Zyklus; der Beitrag bakterieller Menachinone aus dem Kolon ist vermutlich gering.","mangel":"Blutungsneigung (Hämatome, Schleimhaut- und GI-Blutungen) mit erniedrigtem Quick/erhöhter INR bei normaler Thrombozytenzahl. Beim Neugeborenen Vitamin-K-Mangelblutung (früh, klassisch, spät – Spätform oft intrakraniell bei gestillten Kindern); subklinisch untercarboxyliertes Osteocalcin.","risiko":"Neugeborene ohne Prophylaxe (geringer Plazentatransfer, wenig in Muttermilch, steriler Darm), Fettmalabsorption (Cholestase, Mukoviszidose, Zöliakie, Kurzdarm), Langzeitantibiose bei geringer Zufuhr (v. a. Cephalosporine mit N-Methylthiotetrazol-Seitenkette), parenterale Ernährung ohne Vitamin K. Mütterliche Enzyminduktoren (Antikonvulsiva) erhöhen das Risiko früher Neugeborenenblutungen.","ueberdosis":"Phyllochinon und Menachinone gelten als untoxisch; EFSA hat keinen UL abgeleitet. Das synthetische Menadion (K3) kann bei Neugeborenen Hämolyse und Hyperbilirubinämie auslösen. Klinisch relevant ist die Interaktion mit Cumarinen, nicht die Toxizität.","quellen":"K1: grünes Blattgemüse (Grünkohl, Spinat, Mangold), Kohlarten, Pflanzenöle (Raps, Soja); K2: fermentierte Lebensmittel (Natto: MK-7), Käse, Eigelb, Fleisch (MK-4). Die Bioverfügbarkeit von K1 aus Gemüse ist gering und steigt mit Fett.","labor":"Quick/INR ist wenig sensitiv und erst bei deutlichem Mangel pathologisch; sensitiver sind PIVKA-II (des-γ-Carboxy-Prothrombin) und untercarboxyliertes Osteocalcin bzw. dp-ucMGP. Plasma-Phyllochinon spiegelt v. a. die kurzfristige Zufuhr und hängt von den Triglyzeriden ab; Koller-Test: Normalisierung des Quick nach parenteraler Gabe spricht für Mangel statt hepatischer Synthesestörung.","interaktion":"Vitamin-K-Antagonisten (Phenprocoumon, Warfarin) hemmen VKORC1 – schwankende Vitamin-K-Zufuhr destabilisiert die INR, angestrebt wird eine gleichmäßige, nicht eine minimale Zufuhr; DOAKs sind davon unabhängig. Hohe Vitamin-E-Dosen antagonisieren Vitamin K; Colestyramin, Orlistat und Breitbandantibiotika senken die Verfügbarkeit.","ref":{"wert":"m 70 / w 60 µg/Tag (19 bis <51 J.); m 80 / w 65 µg/Tag (ab 51 J.)","art":"Schätzwert","quelle":"https://www.dge.de/wissenschaft/referenzwerte/vitamin-k/","stand":"2000"},"ul":null,"links":{"dis":["vitamin_k_mangel","malassimilation","mukoviszidose","pbc","leberzirrhose","zoeliakie","osteoporose"],"path":["lipoproteine"]},"mcq":[{"q":"Ein Patient mit Quick 45 % zeigt 24 h nach i.v.-Vitamin-K-Gabe keine Besserung. Welche Ursache ist am wahrscheinlichsten?","a":"Verminderte hepatische Syntheseleistung, z. B. bei Leberzirrhose","w":["Fettmalabsorption bei cholestatischer Lebererkrankung mit Ikterus","Langzeit-Antibiose bei geringer Gemüsezufuhr","Unzureichende Vitamin-K-Zufuhr bei Mangelernährung"],"why":"Beim Koller-Test normalisiert sich der Quick bei Vitamin-K-Mangel jeder Ursache, nicht aber bei Synthesestörung, da dort die Faktorproteine selbst fehlen."},{"q":"Welcher Befund zeigt einen subklinischen Vitamin-K-Mangel am sensitivsten an?","a":"Erhöhtes PIVKA-II (des-γ-Carboxy-Prothrombin) im Plasma","w":["Verlängerte aktivierte partielle Thromboplastinzeit (aPTT)","Verminderte Thrombozytenzahl im Blutbild","Erniedrigtes Fibrinogen bei normaler Prothrombinzeit"],"why":"Untercarboxylierte Proteine steigen, bevor Gerinnungstests pathologisch werden; Fibrinogen und Thrombozyten sind Vitamin-K-unabhängig."},{"q":"Eine stabil eingestellte Patientin unter Phenprocoumon trinkt neuerdings täglich große Grünkohl-Smoothies. Was ist zu erwarten?","a":"Die INR sinkt, da Vitamin K über eine warfarinunempfindliche Reduktase aktiviert wird","w":["Die INR steigt, da hohe Vitamin-K-Mengen die Cumarinbindung an VKORC1 allosterisch verstärken","Die INR bleibt gleich, da Nahrungs-Vitamin K Cumarine nicht beeinflusst","Die INR sinkt, da Phyllochinon die Cumarinresorption im Darm blockiert"],"why":"Zugeführtes Chinon kann ohne VKORC1 (u. a. über FSP1) zu KH₂ reduziert werden und die Carboxylierung trotz Cumarin ermöglichen – deshalb gleichmäßige Zufuhr."}]},{"id":"vitamin_b1","name":"Vitamin B1 (Thiamin)","gruppe":"Wasserlösliche Vitamine","aktiveForm":"Thiamindiphosphat (TDP, Thiaminpyrophosphat); daneben Thiamintriphosphat im Nervengewebe","funktion":"TDP ist Koenzym der oxidativen Decarboxylierung durch Pyruvatdehydrogenase, α-Ketoglutaratdehydrogenase und verzweigtkettige α-Ketosäuredehydrogenase sowie der Transketolase im Pentosephosphatweg. Ein Mangel blockiert den aeroben Glukoseabbau (Laktatazidose) und trifft v. a. Neurone und Myokard.","aufnahme":"Aktive, sättigbare Aufnahme im proximalen Dünndarm über THTR-1/-2 (SLC19A2/3), bei hohen Dosen zusätzlich passiv; Alkohol hemmt den Transport. Phosphorylierung zu TDP durch die Thiaminpyrophosphokinase; kleiner Körperbestand mit kurzer Halbwertszeit, die Reserven reichen nur wenige Wochen, Ausscheidung renal.","mangel":"Früh unspezifisch: Müdigkeit, Reizbarkeit, Appetitlosigkeit. Trockene Beriberi: symmetrische sensomotorische Polyneuropathie; feuchte Beriberi: High-Output-Herzinsuffizienz mit Ödemen (fulminant als Shoshin-Beriberi mit Laktatazidose); Wernicke-Enzephalopathie (Augenbewegungsstörung, Ataxie, Verwirrtheit – vollständige Trias selten), unbehandelt Korsakow-Syndrom.","risiko":"Alkoholabhängigkeit (geringe Zufuhr, gehemmte Absorption und Phosphorylierung), Hyperemesis gravidarum, bariatrische Chirurgie, Anorexia nervosa, Refeeding, Dialyse, hochdosierte Schleifendiuretika (renale Verluste), polierter Reis als Hauptnahrung. Thiaminasen (roher Fisch) und Polyphenole (Tee, Betelnuss) inaktivieren Thiamin.","ueberdosis":"Orale Zufuhr nicht toxisch, da Absorption sättigbar und Elimination renal; EFSA hat keinen UL abgeleitet. Sehr selten anaphylaktoide Reaktionen bei parenteraler Gabe.","quellen":"Schweinefleisch, Vollkornprodukte, Hülsenfrüchte, Samen (Sonnenblumenkerne), Kartoffeln. Hitze-, sauerstoff- und wasserempfindlich (DGE: schonend garen, wenig wässern), Sulfit und alkalisches Milieu zerstören Thiamin; Ausmahlen und Polieren entfernen den Großteil.","labor":"Bester Marker ist TDP im Vollblut bzw. in Erythrozyten (HPLC); funktionell die erythrozytäre Transketolaseaktivität mit TDP-Effekt. Serum-Thiamin und Urinausscheidung spiegeln nur die kurzfristige Zufuhr; Wernicke ist eine klinische Diagnose, die Therapie darf nicht auf Laborwerte warten.","interaktion":"Glukosegabe ohne Thiamin kann bei Mangel eine Wernicke-Enzephalopathie auslösen; Schleifendiuretika steigern die renale Ausscheidung, Alkohol hemmt Aufnahme und Aktivierung. Magnesium ist Kofaktor der Thiaminpyrophosphokinase und der TDP-abhängigen Enzyme – eine Hypomagnesiämie kann den Mangel therapierefraktär machen.","ref":{"wert":"m 1,3 / w 1,0 mg/Tag (19 bis <25 J.); m 1,2 / w 1,0 mg (25 bis <65 J.); m 1,1 / w 1,0 mg (ab 65 J.)","art":"Empfehlung","quelle":"https://www.dge.de/wissenschaft/referenzwerte/thiamin/","stand":"2015"},"ul":null,"links":{"dis":["thiaminmangel","wernicke_korsakow","alkoholabhaengigkeit","alkoholische_polyneuropathie","refeeding_syndrom","hyperemesis_gravidarum","herzinsuffizienz","anorexia_nervosa","adipositas"],"path":["pdh","citratzyklus","pentosephosphatweg"]},"mcq":[{"q":"Ein unterernährter Alkoholkranker erhält in der Notaufnahme eine Glukoseinfusion und ist kurz darauf verwirrt mit Nystagmus. Welcher Mechanismus erklärt die Verschlechterung?","a":"Der Glukosefluss steigert den TDP-Bedarf von PDH und α-KGDH und erschöpft die Restreserve","w":["Glukose hemmt kompetitiv den intestinalen Thiamintransporter THTR-1","Hyperglykämie steigert über die osmotische Diurese die renale Thiaminausscheidung um ein Vielfaches","Glukose verdrängt Thiamin aus seiner Bindung an Albumin im Plasma"],"why":"Kohlenhydratlast erhöht den Umsatz TDP-abhängiger Enzyme; deshalb wird Thiamin vor bzw. mit Glukose gegeben."},{"q":"Welcher Befund belegt einen funktionellen Thiaminmangel am spezifischsten?","a":"Deutlich erhöhter TDP-Effekt der Erythrozyten-Transketolase","w":["Erniedrigtes Serum-Thiamin nach einer thiaminarmen Mahlzeit","Erhöhtes Serumlaktat bei Herzinsuffizienz und Schock","Erhöhte Glutathionreduktase-Aktivierung nach FAD-Zusatz"],"why":"Der TDP-Effekt zeigt ungesättigtes Apoenzym an; der FAD-Effekt der Glutathionreduktase ist dagegen der Riboflavinmarker."},{"q":"Ein Patient mit Herzinsuffizienz unter hochdosiertem Furosemid hat zunehmende Ödeme, warme Peripherie und hohes Herzzeitvolumen. Welche ernährungsmedizinische Differenzialdiagnose ist zu prüfen?","a":"Feuchte Beriberi durch diuretikabedingte renale Thiaminverluste","w":["Pellagra durch diuretikabedingte Tryptophanverluste im Urin","Skorbut durch verminderte tubuläre Ascorbatrückresorption","Keshan-Kardiomyopathie durch diuretischen Selenverlust"],"why":"Schleifendiuretika steigern die Thiaminausscheidung; feuchte Beriberi zeigt periphere Vasodilatation mit High-Output-Versagen."}]},{"id":"vitamin_b2","name":"Vitamin B2 (Riboflavin)","gruppe":"Wasserlösliche Vitamine","aktiveForm":"Flavinmononukleotid (FMN) und Flavin-Adenin-Dinukleotid (FAD)","funktion":"FMN/FAD sind prosthetische Gruppen von Oxidoreduktasen: Komplex I (FMN), Succinatdehydrogenase/Komplex II (FAD), Acyl-CoA-Dehydrogenasen der β-Oxidation, E3-Untereinheit von PDH und α-KGDH, Glutathionreduktase. Zudem nötig für andere Vitamine: MTHFR (FAD), Pyridox(am)inphosphat-Oxidase (FMN, PLP-Bildung) und Kynurenin-3-Monooxygenase (Niacinsynthese aus Tryptophan).","aufnahme":"Proteingebundene Flavine werden im oberen Dünndarm freigesetzt und sättigbar über RFVT3 (SLC52A3) aufgenommen. Umwandlung zu FMN (Flavokinase, durch Schilddrüsenhormone stimuliert) und FAD; kaum Speicherung, Überschuss wird renal ausgeschieden (gelber Urin).","mangel":"Ariboflavinose meist mit anderen B-Vitamin-Defiziten: Cheilitis angularis, Cheilosis, Glossitis, seborrhoische Dermatitis, Hornhautvaskularisation; bei schwerem Mangel normochrome Anämie und sekundäre Störungen von B6- und Niacinstoffwechsel. Defekte der Riboflavintransporter (SLC52A2/3) verursachen das Brown-Vialetto-Van-Laere-Syndrom.","risiko":"Alkoholabhängigkeit, geringe Milch- und Fleischzufuhr (vegan potenziell kritisch, DGE), höheres Alter, Hypothyreose (verminderte FMN/FAD-Bildung), Malabsorption. Medikamente: Phenothiazine und trizyklische Antidepressiva (strukturähnlich, hemmen die Flavokinase), Phenobarbital; Phototherapie bei Neugeborenen (Photodegradation).","ueberdosis":"Nicht toxisch, da Absorption sättigbar und renale Ausscheidung rasch (intensiv gelber Urin); EFSA hat keinen UL abgeleitet.","quellen":"Milch und Milchprodukte, Fleisch, Innereien (Leber, Niere), Fisch, Eier, Vollkorn. Sehr lichtempfindlich und wasserlöslich (DGE: dunkel lagern, Kochwasser mitverwenden).","labor":"Funktioneller Marker ist der Aktivierungskoeffizient der Erythrozyten-Glutathionreduktase (EGRAC, FAD-Effekt); bei G6PD-Mangel nicht aussagekräftig. Urinausscheidung spiegelt die kurzfristige Zufuhr; ein erhöhtes Homocystein bei MTHFR-677TT kann einen niedrigen Riboflavinstatus anzeigen.","interaktion":"Riboflavinmangel verursacht funktionelle Defizite anderer Vitamine: weniger PLP (FMN-abhängige Oxidase), geringere MTHFR-Aktivität (FAD) und verminderte Niacinsynthese aus Tryptophan. Phenothiazine, Trizyklika und Alkohol beeinträchtigen den Status; Schilddrüsenhormone fördern die Flavinaktivierung.","ref":{"wert":"m 1,4 / w 1,1 mg/Tag (19 bis <51 J.); m 1,3 / w 1,0 mg/Tag (ab 51 J.)","art":"Empfehlung","quelle":"https://www.dge.de/wissenschaft/referenzwerte/riboflavin/","stand":"2015"},"ul":null,"links":{"dis":["migraene","alkoholabhaengigkeit","hypothyreose"],"path":["atmungskette","citratzyklus","beta-oxidation","pdh","methylierungszyklus"]},"mcq":[{"q":"Bei Homozygotie für MTHFR 677C>T ist Homocystein erhöht, Folat und B12 sind normal. Welcher Nährstoff moduliert die Enzymaktivität besonders?","a":"Riboflavin, da die thermolabile MTHFR ihren Kofaktor FAD leichter verliert","w":["Thiamin, da die MTHFR TDP als Kofaktor einer Decarboxylierung nutzt","Biotin, da die MTHFR eine biotinabhängige Carboxylase darstellt","Niacin, da die MTHFR ausschließlich NAD⁺ als Elektronenakzeptor der Reaktion nutzt"],"why":"Die 677TT-Variante dissoziiert vermehrt FAD; bei niedrigem Riboflavinstatus steigt Homocystein besonders, eine bessere Versorgung senkt es genotypspezifisch."},{"q":"Welcher Befund weist am spezifischsten auf einen Riboflavinmangel hin?","a":"Erhöhter Aktivierungskoeffizient der Erythrozyten-Glutathionreduktase","w":["Erhöhter TDP-Effekt der Erythrozyten-Transketolase","Erhöhte Xanthurensäureausscheidung im Urin nach oraler Tryptophanbelastung","Erhöhte Methylmalonsäure bei normalem Homocystein"],"why":"Die Glutathionreduktase ist FAD-abhängig; ihr FAD-Effekt (EGRAC) ist der funktionelle Riboflavinmarker, die übrigen gehören zu B1, B6 bzw. B12."},{"q":"Ein schwerer Riboflavinmangel kann einen funktionellen Vitamin-B6-Mangel verursachen. Auf welcher Ebene?","a":"Die PLP-Bildung durch die FMN-abhängige Pyridox(am)inphosphat-Oxidase sinkt","w":["Die intestinale Pyridoxinaufnahme benötigt FAD als Transportkofaktor","PLP wird ohne ausreichend FAD vermehrt renal als 4-Pyridoxinsäure ausgeschieden","Die Pyridoxalkinase ist ein FAD-haltiges Flavoprotein der Leber"],"why":"PNPO oxidiert PNP und PMP mit FMN zu PLP; ohne ausreichend FMN sinkt der PLP-Spiegel trotz B6-Zufuhr."}]},{"id":"vitamin_b3","name":"Vitamin B3 (Niacin)","gruppe":"Wasserlösliche Vitamine","aktiveForm":"NAD⁺/NADH und NADP⁺/NADPH (aus Nicotinsäure, Nicotinamid oder Tryptophan gebildet)","funktion":"NAD⁺ ist Elektronenakzeptor katabolischer Dehydrogenasen (GAPDH, PDH, Citratzyklus, β-Oxidation, Alkohol- und Aldehyddehydrogenase), NADH speist Komplex I; NADPH dient Biosynthesen (Fettsäuren, Cholesterin) und dem Glutathionsystem. NAD⁺ ist außerdem Substrat von Sirtuinen, PARP (DNA-Reparatur) und ADP-Ribosyltransferasen.","aufnahme":"Nicotinsäure und Nicotinamid werden im Dünndarm rasch aufgenommen; endogene Synthese aus Tryptophan über den Kynureninweg (DGE: 60 mg Tryptophan = 1 mg Niacinäquivalent), abhängig von B6, B2 und Eisen. Abbau zu N1-Methylnicotinamid und 2-Pyridon mit renaler Ausscheidung; in Mais liegt Niacin überwiegend gebunden (Niacytin) vor und wird erst durch Nixtamalisation (Alkalibehandlung) verfügbar.","mangel":"Pellagra mit Dermatitis an lichtexponierten Stellen (Casal-Halsband), Diarrhö mit Glossitis und Stomatitis sowie Demenz/Enzephalopathie, unbehandelt Tod. Frühzeichen unspezifisch: Schwäche, Appetitlosigkeit, Depression, Reizbarkeit.","risiko":"Alkoholabhängigkeit, Anorexia nervosa, maisbasierte Kost ohne Nixtamalisation, Malabsorption, Leberzirrhose (DGE); Karzinoidsyndrom (Tryptophan wird zu Serotonin umgeleitet), Hartnup-Krankheit (SLC6A19-Defekt). Medikamente: Isoniazid (PLP-Antagonismus hemmt den Kynureninweg), seltener Azathioprin und 5-Fluorouracil.","ueberdosis":"Nicotinsäure (nicht Nicotinamid) verursacht schon in niedriger Dosis einen prostaglandinvermittelten Flush über den Rezeptor HCA2 (GPR109A) – Grundlage des niedrigen EFSA-UL. Hochdosiert zusätzlich Hepatotoxizität (v. a. Retardpräparate), Hyperurikämie, Verschlechterung der Glukosetoleranz und Makulaödem; für Nicotinamid gilt ein deutlich höherer UL.","quellen":"Fleisch, Geflügel, Fisch, Innereien, Erdnüsse, Pilze, Brot und Vollkorn; tierisches Protein liefert zusätzlich Tryptophan. Niacin aus Getreide ist schlechter verfügbar als aus tierischen Lebensmitteln (DGE); wasserlöslich, Kochwasser mitverwenden.","labor":"Kein etablierter Einzelmarker; gebräuchlich sind die Urinmetaboliten N1-Methylnicotinamid und 2-Pyridon (Quotient sinkt bei Mangel) sowie der erythrozytäre NAD/NADP-Quotient (Niacin-Index). Die Diagnose der Pellagra ist primär klinisch.","interaktion":"Die Tryptophan-Niacin-Synthese erfordert PLP (Kynureninase), FAD (Kynurenin-3-Monooxygenase) und Eisen; B6-, B2-Mangel oder Isoniazid begünstigen daher Pellagra. Nicotinsäure plus Statin erhöht das Myopathierisiko und verschlechtert die Glukosekontrolle unter Antidiabetika; hohe Nicotinamidmengen verbrauchen Methylgruppen (Methylierung zu N1-Methylnicotinamid).","ref":{"wert":"m 16 / w 13 mg Niacinäquivalente/Tag (19 bis <25 J.); m 15 / w 12 (25 bis <51 J.); m 15 / w 11 (51 bis <65 J.); m 14 / w 11 (ab 65 J.)","art":"Empfehlung","quelle":"https://www.dge.de/wissenschaft/referenzwerte/niacin/","stand":"2015"},"ul":{"wert":"Nicotinsäure 10 mg/Tag; Nicotinamid 900 mg/Tag","art":"UL","quelle":"https://www.efsa.europa.eu/sites/default/files/2024-05/ul-summary-report.pdf (EFSA: Overview on Tolerable Upper Intake Levels, Version 11 (August 2025); Grundlage: SCF 2002)"},"links":{"dis":["pellagra","alkoholabhaengigkeit","net_duenndarm","tuberkulose","anorexia_nervosa","leberzirrhose","gicht"],"path":["glykolyse","citratzyklus","atmungskette","pentosephosphatweg","fettsaeuresynthese","beta-oxidation","alkoholabbau"]},"mcq":[{"q":"Ein Patient mit metastasiertem Dünndarm-NET und Flush entwickelt eine Dermatitis an Hals und Handrücken sowie Durchfälle. Welcher Mechanismus erklärt den Niacinmangel?","a":"Tryptophan wird bevorzugt zu Serotonin statt über den Kynureninweg zu NAD⁺ umgesetzt","w":["Serotonin hemmt kompetitiv die intestinale Aufnahme von Nicotinsäure","Der Tumor verbraucht das zirkulierende NAD⁺ direkt über eine stark gesteigerte PARP-Aktivität","Chromogranin A bindet Niacin im Plasma und steigert dessen Ausscheidung"],"why":"Beim Karzinoidsyndrom fließt ein Großteil des Tryptophans in die Serotoninsynthese, sodass die endogene Niacinbildung fehlt."},{"q":"Warum trat Pellagra bei maisbasierter Ernährung in Südeuropa auf, kaum aber in Mittelamerika trotz ähnlich hohen Maisverzehrs?","a":"Nixtamalisation mit Kalk setzt das gebundene Niacin (Niacytin) frei","w":["Mittelamerikanische Maissorten enthalten deutlich mehr freies Tryptophan","Mais wurde dort fermentiert, wobei Bakterien Niacin de novo bilden","Capsaicin aus Chili hemmt die renale Ausscheidung von Nicotinamid"],"why":"Die alkalische Behandlung hydrolysiert die Esterbindung des Niacins; Mais ist zudem tryptophanarm, sodass die endogene Synthese nicht kompensiert."},{"q":"Warum ist der EFSA-UL für Nicotinsäure um ein Vielfaches niedriger als für Nicotinamid?","a":"Nur Nicotinsäure aktiviert HCA2 und löst einen prostaglandinvermittelten Flush aus","w":["Nur Nicotinsäure wird in der Leber zu Tryptophan zurückverwandelt und akkumuliert dort","Nicotinamid wird nicht resorbiert und kann daher nicht toxisch wirken","Nicotinsäure hemmt die NAD⁺-Synthese und verursacht so eine Pellagra"],"why":"Der HCA2-(GPR109A-)vermittelte Flush tritt schon bei niedrigen Nicotinsäuredosen auf; Nicotinamid bindet den Rezeptor nicht."}]},{"id":"vitamin_b5","name":"Vitamin B5 (Pantothensäure)","gruppe":"Wasserlösliche Vitamine","aktiveForm":"Coenzym A (CoA) und 4'-Phosphopantethein (prosthetische Gruppe des Acyl-Carrier-Proteins der Fettsäuresynthase)","funktion":"CoA aktiviert Carbonsäuren als energiereiche Thioester (Acetyl-, Succinyl-, Malonyl-, HMG-, Acyl-CoA) und ist damit zentral für PDH- und α-KGDH-Reaktion, β-Oxidation, Ketogenese, Cholesterin-, Häm- und Acetylcholinsynthese sowie Acetylierungen. 4'-Phosphopantethein trägt als Schwingarm die wachsende Acylkette am ACP der Fettsäuresynthase.","aufnahme":"Nahrungs-CoA wird im Lumen über Pantethein zu Pantothensäure hydrolysiert und über den natriumabhängigen Multivitamintransporter SMVT (SLC5A6) aufgenommen, den es mit Biotin und Liponsäure teilt. Geschwindigkeitsbestimmend für die CoA-Synthese ist die Pantothenatkinase (PANK, durch Acyl-CoA feedbackgehemmt); Ausscheidung renal.","mangel":"Isolierter Mangel nur experimentell oder bei schwerster Mangelernährung: Parästhesien und brennende Füße (burning feet syndrome), Müdigkeit, Schlafstörungen, GI-Beschwerden. Der genetische PANK2-Defekt (PKAN, Neurodegeneration mit Eisenablagerung, Tigeraugenzeichen) ist kein Ernährungsmangel.","risiko":"Schwere Mangelernährung und Alkoholabhängigkeit, meist kombiniert mit anderen B-Vitamin-Defiziten; klinisch relevante arzneimittelbedingte Mängel sind nicht gut belegt.","ueberdosis":"Sehr geringe Toxizität, hohe Dosen allenfalls Durchfall; EFSA hat keinen UL abgeleitet.","quellen":"Nahezu ubiquitär: Leber, Fleisch, Eier, Vollkorn, Hülsenfrüchte, Pilze, Avocado. Verluste durch Erhitzen, Einfrieren und industrielle Verarbeitung.","labor":"Kein validierter Statusmarker; die Urinausscheidung korreliert mit der Zufuhr, Vollblut-Pantothensäure wird ergänzend verwendet. Die klinische Relevanz der Bestimmung ist gering.","interaktion":"Teilt den SMVT-Transporter mit Biotin und Liponsäure – sehr hohe Dosen einer Substanz können die Aufnahme der anderen kompetitiv mindern. Gesicherte relevante Arzneimittelinteraktionen sind nicht bekannt.","ref":{"wert":"5 mg/Tag (Erwachsene, m und w)","art":"Schätzwert","quelle":"https://www.dge.de/wissenschaft/referenzwerte/pantothensaeure/","stand":"2021"},"ul":null,"links":{"dis":[],"path":["pdh","citratzyklus","beta-oxidation","fettsaeuresynthese","cholesterinsynthese","ketonkoerper","haem-bilirubin"]},"mcq":[{"q":"Ein Jugendlicher mit progredienter Dystonie zeigt im T2-MRT ein Tigeraugenzeichen im Globus pallidus. Welcher Stoffwechselschritt ist betroffen?","a":"Phosphorylierung von Pantothensäure als erster Schritt der CoA-Synthese","w":["Hydrolyse von Nahrungs-CoA im Darmlumen durch Pantetheinasen","Natriumabhängige Pantothensäureaufnahme über SMVT im Jejunum","Bildung von Acetyl-CoA aus Pyruvat durch die mitochondriale Pyruvatdehydrogenase"],"why":"PKAN beruht auf PANK2-Mutationen; die mitochondriale Pantothenatkinase katalysiert den geschwindigkeitsbestimmenden ersten Schritt der CoA-Synthese."},{"q":"Welche Struktur nutzt die Fettsäuresynthase als Schwingarm, der die wachsende Acylkette als Thioester bindet?","a":"4'-Phosphopantethein am Acyl-Carrier-Protein","w":["Liponsäure am Lysin der E2-Untereinheit","Biotin an einem Lysinrest der Carboxylase","Thiamindiphosphat mit seinem Thiazoliumring"],"why":"Der pantothensäureabgeleitete Phosphopantethein-Arm transportiert die Acylkette zwischen den katalytischen Zentren; Liponsäure erfüllt diese Rolle bei PDH und α-KGDH."},{"q":"Über welches CoA-Derivat ist Pantothensäure direkt an der Hämsynthese beteiligt?","a":"Succinyl-CoA als Substrat der δ-Aminolävulinsäure-Synthase","w":["Acetyl-CoA als Substrat der Porphobilinogen-Synthase","Malonyl-CoA als Substrat der Ferrochelatase","HMG-CoA als Substrat der zytosolischen Uroporphyrinogen-Decarboxylase"],"why":"Die PLP-abhängige ALA-Synthase kondensiert Glycin mit Succinyl-CoA im Mitochondrium; die übrigen Zuordnungen sind falsch."}]},{"id":"vitamin_b6","name":"Vitamin B6 (Pyridoxin)","gruppe":"Wasserlösliche Vitamine","aktiveForm":"Pyridoxal-5'-phosphat (PLP); Vorstufen Pyridoxin, Pyridoxal, Pyridoxamin und deren Phosphate","funktion":"PLP ist Koenzym von weit über hundert Enzymen des Aminosäurestoffwechsels: Transaminasen (ALT, AST), Decarboxylasen (Serotonin, Dopamin, GABA, Histamin), ALA-Synthase (Hämsynthese), Cystathionin-β-Synthase und γ-Lyase (Transsulfuration), Serinhydroxymethyltransferase (C1-Stoffwechsel) und Kynureninase (Niacinsynthese). Zudem Kofaktor der Glykogenphosphorylase.","aufnahme":"Phosphorylierte Formen werden durch intestinale Phosphatasen gespalten und passiv aufgenommen; in der Leber Rephosphorylierung (Pyridoxalkinase) und Oxidation zu PLP (FMN-abhängige PNPO). Plasma-PLP ist an Albumin gebunden und muss zur Zellaufnahme durch die alkalische Phosphatase zu Pyridoxal dephosphoryliert werden; größter Speicher ist PLP an der Muskel-Glykogenphosphorylase, Abbau zu 4-Pyridoxinsäure.","mangel":"Seborrhoische Dermatitis, Cheilosis, Glossitis, mikrozytäre (sideroblastische) Anämie, periphere Neuropathie, Depression und Verwirrtheit; bei Säuglingen Krampfanfälle (verminderte GABA-Synthese). Die pyridoxinabhängige Epilepsie (ALDH7A1) ist ein genetischer Defekt mit Ansprechen auf Pyridoxin.","risiko":"Alkoholabhängigkeit (Acetaldehyd fördert PLP-Abbau), Niereninsuffizienz und Dialyse, höheres Alter, chronische Entzündung. Medikamente, die PLP binden oder inaktivieren: Isoniazid, Hydralazin, Penicillamin, Cycloserin, Levodopa; Antiepileptika (Enzyminduktion).","ueberdosis":"Chronisch hohe Supplementzufuhr verursacht eine sensible axonale Polyneuropathie (Parästhesien, Gangunsicherheit) – Grundlage des EFSA-UL (2023); Fälle wurden auch bei moderaten Supplementdosen berichtet. Über Lebensmittel nicht erreichbar.","quellen":"Fleisch, Geflügel, Fisch, Innereien, Kartoffeln, Hülsenfrüchte, Bananen, Vollkorn, Nüsse. In Pflanzen teils als Pyridoxin-5'-β-Glucosid mit geringerer Bioverfügbarkeit; hitzeempfindlich.","labor":"Plasma-PLP ist der gebräuchlichste Marker, sinkt aber bei Entzündung und Hypalbuminämie unabhängig vom Gewebestatus und steigt nach Supplementen rasch. Bei Hypophosphatasie ist Plasma-PLP stark erhöht trotz intrazellulärem Mangel; funktionell: erythrozytäre Transaminase-Aktivierungskoeffizienten, Xanthurensäure nach Tryptophanbelastung, HK:XA-Quotient.","interaktion":"Isoniazid bildet mit PLP inaktive Hydrazone (Neuropathie-, Pellagra- und sideroblastisches Risiko). Pyridoxin beschleunigt die periphere Decarboxylierung von Levodopa ohne Decarboxylasehemmer (Wirkverlust); Riboflavin ist für die PLP-Bildung nötig, PLP für Transsulfuration und Niacinsynthese.","ref":{"wert":"m 1,6 / w 1,4 mg/Tag (Erwachsene)","art":"Empfehlung","quelle":"https://www.dge.de/wissenschaft/referenzwerte/vitamin-b6/","stand":"2019"},"ul":{"wert":"12 mg/Tag","art":"UL","quelle":"https://www.efsa.europa.eu/sites/default/files/2024-05/ul-summary-report.pdf (EFSA: Overview on Tolerable Upper Intake Levels, Version 11 (August 2025); Grundlage: EFSA NDA Panel 2023)"},"links":{"dis":["sideroblastische_anaemie","homocystinurie","tuberkulose","parkinson","epilepsie","alkoholabhaengigkeit","chronische_nierenkrankheit"],"path":["methylierungszyklus","haem-bilirubin","glykogen"]},"mcq":[{"q":"Eine Patientin mit Hypophosphatasie (stark erniedrigte alkalische Phosphatase) hat ein stark erhöhtes Plasma-PLP, aber Krampfanfälle. Wie passt das zusammen?","a":"Ohne AP-Dephosphorylierung gelangt PLP nicht in die Zellen – intrazellulärer Mangel","w":["Erhöhtes PLP hemmt die GABA-Synthese durch Substratüberschuss im Gehirn","Hohe PLP-Spiegel belegen eine Vitamin-B6-Intoxikation durch Supplemente","Die AP baut PLP direkt zu 4-Pyridoxinsäure ab, der Anstieg bleibt daher klinisch folgenlos"],"why":"PLP passiert Membranen erst als Pyridoxal; TNSALP-Mangel erhöht extrazelluläres PLP und senkt zerebrales PLP (pyridoxinresponsive Krampfanfälle)."},{"q":"Unter Tuberkulosetherapie entwickelt ein Patient mit Alkoholabhängigkeit Parästhesien und eine mikrozytäre Anämie mit Ringsideroblasten. Welche Erklärung ist am wahrscheinlichsten?","a":"Isoniazid-induzierter PLP-Mangel mit verminderter ALA-Synthase-Aktivität","w":["Rifampicin-induzierter Folatmangel mit gestörter Thymidylatsynthese","Isoniazid-induzierte Bleiretention mit Hemmung der Ferrochelatase","Pyrazinamid-induzierte Hyperurikämie mit Hemmung der Hämoxygenase"],"why":"Isoniazid inaktiviert PLP; die erythroide ALA-Synthase ist PLP-abhängig, ihr Ausfall verursacht eine sideroblastische Anämie, Alkohol verstärkt den PLP-Abbau."},{"q":"Ein Parkinsonpatient unter Levodopa-Monotherapie ohne Decarboxylasehemmer beginnt ein hochdosiertes B6-Präparat. Was ist zu erwarten?","a":"Wirkverlust, da PLP die periphere Decarboxylierung von Levodopa beschleunigt","w":["Wirkverstärkung, da PLP den Levodopa-Transport ins Gehirn steigert","Keine Änderung, da die Dopa-Decarboxylase PLP-unabhängig arbeitet","Wirkverlust, da Pyridoxin den intestinalen Aminosäuretransport von Levodopa kompetitiv blockiert"],"why":"Die aromatische L-Aminosäure-Decarboxylase ist PLP-abhängig; mit Carbidopa oder Benserazid ist die Interaktion klinisch irrelevant."}]},{"id":"vitamin_b7","name":"Vitamin B7 (Biotin)","gruppe":"Wasserlösliche Vitamine","aktiveForm":"Kovalent an ein Lysin der Carboxylasen gebundenes Biotin (Biocytinrest), angeheftet durch die Holocarboxylase-Synthetase","funktion":"Prosthetische Gruppe von fünf ATP-abhängigen Carboxylasen, die CO₂ aus Bicarbonat übertragen: Acetyl-CoA-Carboxylase 1/2 (Fettsäuresynthese, Hemmung der β-Oxidation über Malonyl-CoA), Pyruvatcarboxylase (Glukoneogenese, Anaplerose), Propionyl-CoA-Carboxylase (Abbau von Val, Ile, Met, Thr und ungeradzahligen Fettsäuren) und 3-Methylcrotonyl-CoA-Carboxylase (Leucinabbau).","aufnahme":"Proteingebundenes Biotin wird durch Biotinidase freigesetzt und über SMVT (SLC5A6) im Dünndarm aufgenommen; der Beitrag mikrobieller Synthese im Kolon ist unklar. Biotinidase recycelt Biotin aus abgebauten Carboxylasen; Ausscheidung renal.","mangel":"Periorifizielle schuppende Dermatitis, Alopezie, Konjunktivitis, Lethargie, Depression, Parästhesien, Muskelhypotonie; bei Kindern Krampfanfälle und Entwicklungsverzögerung, organische Azidurie. Angeborener Biotinidase- oder Holocarboxylase-Synthetase-Mangel verursacht einen multiplen Carboxylasemangel (Neugeborenenscreening).","risiko":"Regelmäßiger Verzehr großer Mengen roher Eier (Avidin bindet Biotin), Biotinidasemangel, Langzeittherapie mit Antikonvulsiva (Carbamazepin, Phenytoin, Phenobarbital), parenterale Ernährung ohne Biotin, Alkoholabhängigkeit; in der Schwangerschaft ist ein marginaler Status beschrieben.","ueberdosis":"Keine Toxizität bekannt; EFSA hat keinen UL abgeleitet. Klinisch relevant ist, dass Hochdosis-Supplemente (z. B. für Haare und Nägel) Streptavidin-Biotin-Immunoassays verfälschen.","quellen":"Leber, Eigelb, Sojabohnen, Nüsse, Haferflocken, Hefe, Pilze. Biotin aus gegartem Ei ist verfügbar, da Hitze das Avidin denaturiert.","labor":"Funktionell: Urinausscheidung von 3-Hydroxyisovaleriansäure (↑) und Biotin (↓), Propionyl-CoA-Carboxylase-Aktivität in Lymphozyten; Serumbiotin ist wenig sensitiv. Wichtiger Fallstrick: Biotineinnahme macht Sandwich-Immunoassays falsch niedrig (TSH, Troponin) und kompetitive Assays falsch hoch (fT4, fT3, TRAK).","interaktion":"Avidin aus rohem Eiklar bindet Biotin nahezu irreversibel; Antikonvulsiva senken den Status; Biotin teilt den SMVT mit Pantothensäure und Liponsäure. Vor Immunoassays Biotinpräparate nach Herstellerangaben pausieren.","ref":{"wert":"40 µg/Tag (Erwachsene, m und w)","art":"Schätzwert","quelle":"https://www.dge.de/wissenschaft/referenzwerte/biotin/","stand":"2020"},"ul":null,"links":{"dis":["hyperthyreose","morbus_basedow","epilepsie"],"path":["glukoneogenese","fettsaeuresynthese","citratzyklus"]},"mcq":[{"q":"Eine Patientin, die hochdosiert Biotin für Haare und Nägel nimmt, hat supprimiertes TSH und erhöhtes fT4 ohne klinische Hyperthyreose. Was ist die wahrscheinlichste Erklärung?","a":"Assay-Interferenz: Sandwich-Assay (TSH) falsch niedrig, kompetitiver Assay (fT4) falsch hoch","w":["Biotininduzierte destruierende Thyreoiditis mit Freisetzung präformierter Schilddrüsenhormone","Biotin steigert die Dejodaseaktivität und damit die periphere fT4-Bildung","Biotin stimuliert den TSH-Rezeptor ähnlich wie TRAK beim Morbus Basedow"],"why":"Freies Biotin blockiert die Streptavidin-Bindung; das Muster imitiert einen Morbus Basedow, auch TRAK kann falsch positiv ausfallen."},{"q":"Ein Säugling mit Hautausschlag, Alopezie, Krampfanfällen und organischer Azidurie bessert sich unter Biotin. Welcher Defekt ist am wahrscheinlichsten?","a":"Biotinidasemangel mit gestörtem Biotin-Recycling","w":["Pyruvatdehydrogenase-Mangel mit Thiaminresponsivität","Methylmalonyl-CoA-Mutase-Defekt mit B12-Responsivität","Phenylalaninhydroxylase-Mangel mit BH4-Responsivität"],"why":"Biotinidase spaltet Biocytin; ihr Fehlen verursacht einen multiplen Carboxylasemangel, der im Neugeborenenscreening erfasst wird."},{"q":"Welcher Urinmetabolit zeigt einen marginalen Biotinmangel am frühesten an?","a":"3-Hydroxyisovaleriansäure durch verminderte Methylcrotonyl-CoA-Carboxylase","w":["Methylmalonsäure durch verminderte Aktivität der mitochondrialen Methylmalonyl-CoA-Mutase","Formiminoglutamat durch verminderte Folatverfügbarkeit","Xanthurensäure durch verminderte Kynureninase-Aktivität"],"why":"Bei Biotinmangel stockt der Leucinabbau, 3-Methylcrotonyl-CoA wird zu 3-Hydroxyisovaleriansäure umgeleitet; die übrigen Marker gehören zu B12, Folat bzw. B6."}]},{"id":"vitamin_b9","name":"Folat (Vitamin B9)","gruppe":"Wasserlösliche Vitamine","aktiveForm":"Tetrahydrofolat (THF) und C1-Derivate: 5-Methyl-THF (Hauptform im Plasma), 5,10-Methylen-THF, 10-Formyl-THF; intrazellulär als Polyglutamate","funktion":"THF überträgt C1-Einheiten: 5,10-Methylen-THF für die Thymidylatsynthase (dUMP → dTMP), 10-Formyl-THF für die Purinsynthese und 5-Methyl-THF für die B12-abhängige Methioninsynthase (Homocystein → Methionin, SAM-Bildung). Daher zentral für Zellteilung (Erythropoese, Embryogenese, Neuralrohrschluss) und Methylierungsreaktionen.","aufnahme":"Nahrungsfolat-Polyglutamate werden im Bürstensaum durch die Glutamatcarboxypeptidase II zu Monoglutamaten gespalten und über den protonengekoppelten Folattransporter PCFT (SLC46A1) im proximalen Jejunum aufgenommen. Synthetische Folsäure muss durch die beim Menschen langsame DHFR reduziert werden (bei hoher Zufuhr zirkuliert unmetabolisierte Folsäure); Speicher v. a. in der Leber für Wochen bis wenige Monate, enterohepatischer Kreislauf.","mangel":"Megaloblastäre, makrozytäre Anämie mit hypersegmentierten Neutrophilen, Glossitis, ggf. Panzytopenie; Homocystein ↑. Perikonzeptionell erhöhtes Risiko für Neuralrohrdefekte; anders als bei B12-Mangel keine funikuläre Myelose, neuropsychiatrische Symptome (Depression) sind möglich.","risiko":"Geringe Gemüsezufuhr, Alkoholabhängigkeit, Schwangerschaft und Stillzeit, gesteigerter Zellumsatz (Hämolyse), Zöliakie, Morbus Crohn, Kurzdarm. Medikamente: DHFR-Hemmer (Methotrexat, Trimethoprim, Pyrimethamin), Antiepileptika (Phenytoin, Carbamazepin, Valproat), Sulfasalazin (hemmt die Aufnahme).","ueberdosis":"Nahrungsfolat gilt als untoxisch; der EFSA-UL gilt nur für Folsäure und andere zugesetzte synthetische Folate. Kritischer Effekt: Hohe Folsäurezufuhr korrigiert die Anämie eines B12-Mangels und kann so die Diagnose verzögern, während die neurologische Schädigung fortschreitet.","quellen":"Grünes Blattgemüse (Spinat, Feldsalat), Kohl (Brokkoli, Rosenkohl), Hülsenfrüchte, Leber, Vollkorn, Eigelb, Weizenkeime; hitze-, licht- und oxidationsempfindlich. Nahrungsfolat ist nur etwa halb so gut verfügbar wie Folsäure (DGE: 1 µg Folatäquivalent = 1 µg Nahrungsfolat = 0,5 µg Folsäure).","labor":"Serumfolat spiegelt die kurzfristige Zufuhr (steigt schon nach einer folatreichen Mahlzeit), Erythrozytenfolat die Versorgung der letzten Monate. Homocystein ist unspezifisch (auch B12, B6, B2, Niereninsuffizienz, Hypothyreose); normale MMA spricht gegen einen B12-Mangel, bei B12-Mangel kann Serumfolat erhöht und Erythrozytenfolat erniedrigt sein (Methylfolat-Falle).","interaktion":"B12 führt 5-Methyl-THF über die Methioninsynthase in den Folatpool zurück; fehlt es, bleibt Folat als 5-Methyl-THF gefangen. Riboflavin (FAD) und die MTHFR-677TT-Variante modulieren die 5-Methyl-THF-Bildung; DHFR-Hemmer und Antiepileptika senken den Status, hohe Folsäuredosen können umgekehrt Phenytoinspiegel senken.","ref":{"wert":"300 µg Folatäquivalente/Tag (Erwachsene, m und w); Frauen, die schwanger werden wollen oder könnten, zusätzlich 400 µg synthetische Folsäure/Tag","art":"Empfehlung","quelle":"https://www.dge.de/wissenschaft/referenzwerte/folat/","stand":"2015"},"ul":{"wert":"1000 µg/Tag (nur Folsäure und andere zugesetzte synthetische Folate, nicht Nahrungsfolat)","art":"UL","quelle":"https://www.efsa.europa.eu/sites/default/files/2024-05/ul-summary-report.pdf (EFSA: Overview on Tolerable Upper Intake Levels, Version 11 (August 2025); Grundlage: EFSA NDA Panel 2023)"},"links":{"dis":["folsaeuremangel","folsaeuremangel_anaemie","neuralrohrdefekte","spina_bifida","vitamin_b12_mangel","alkoholabhaengigkeit","zoeliakie","morbus_crohn","rheumatoide_arthritis","epilepsie"],"path":["methylierungszyklus"]},"mcq":[{"q":"Bei makrozytärer Anämie sind Serumfolat hochnormal, Erythrozytenfolat niedrig, Methylmalonsäure und Homocystein erhöht. Was ist die wahrscheinlichste Ursache?","a":"Vitamin-B12-Mangel mit Methylfolat-Falle","w":["Isolierter Folatmangel durch geringe Gemüsezufuhr","Folsäureüberdosierung durch angereicherte Lebensmittel","Vitamin-B6-Mangel mit gestörter Transsulfuration"],"why":"Ohne B12 bleibt Folat als 5-Methyl-THF gefangen und wird schlechter polyglutamyliert und in Zellen gehalten; die MMA-Erhöhung ist spezifisch für B12."},{"q":"Unter Methotrexat bei rheumatoider Arthritis wird häufig Folsäure ergänzt. Welcher Mechanismus begründet den Folatantagonismus von Methotrexat?","a":"Hemmung der Dihydrofolatreduktase, sodass reduziertes THF fehlt","w":["Hemmung der Methioninsynthase, sodass 5-Methyl-THF akkumuliert","Hemmung des Transporters PCFT, sodass keine Folataufnahme erfolgt","Hemmung der Glutamatcarboxypeptidase im Bürstensaum des Jejunums"],"why":"Methotrexat ist ein hochaffiner DHFR-Hemmer; die Folsäuregabe vermindert Nebenwirkungen wie Mukositis und Transaminasenanstieg."},{"q":"Warum soll die perikonzeptionelle Folsäure-Einnahme bereits vor der Schwangerschaft beginnen?","a":"Der Neuralrohrschluss ist um den 28. Tag post conceptionem abgeschlossen","w":["Folsäure benötigt etwa ein Jahr, um die Leberspeicher aufzufüllen","Folsäure wird im ersten Trimenon intestinal nicht mehr resorbiert","Folsäure verhindert bei bestehendem Mangel bereits die Konzeption"],"why":"Der Neuralrohrverschluss erfolgt in der 3.–4. Woche nach Konzeption, oft vor Kenntnis der Schwangerschaft; die DGE nennt mindestens 4 Wochen Vorlauf."}]},{"id":"vitamin_b12","name":"Vitamin B12 (Cobalamin)","gruppe":"Wasserlösliche Vitamine","aktiveForm":"Methylcobalamin (Methioninsynthase, Zytosol) und 5'-Desoxyadenosylcobalamin (Methylmalonyl-CoA-Mutase, Mitochondrium)","funktion":"Methylcobalamin ist Kofaktor der Methioninsynthase (Homocystein + 5-Methyl-THF → Methionin + THF) und verbindet Methylierungs- und Folatzyklus. 5'-Desoxyadenosylcobalamin isomerisiert L-Methylmalonyl-CoA zu Succinyl-CoA (Abbau von Val, Ile, Met, Thr und ungeradzahligen Fettsäuren); Mangel führt zu Homocystein- und MMA-Anstieg, gestörter DNA-Synthese und Myelinschädigung.","aufnahme":"Magensäure und Pepsin lösen B12 aus Proteinen, es bindet zunächst an Haptocorrin; im Duodenum spalten Pankreasproteasen Haptocorrin, B12 bindet an Intrinsic Factor und wird im terminalen Ileum über Cubam (Cubilin/Amnionless) calciumabhängig aufgenommen. Transport an Transcobalamin (Holotranscobalamin = gewebsverfügbare Fraktion); großer Leberspeicher und enterohepatischer Kreislauf, daher entwickelt sich ein Mangel über Jahre; etwa 1 % wird IF-unabhängig passiv aufgenommen.","mangel":"Hämatologisch: megaloblastäre Anämie, hypersegmentierte Neutrophile, ggf. Panzytopenie, LDH und indirektes Bilirubin ↑ (ineffektive Erythropoese), Hunter-Glossitis. Neurologisch, auch ohne Anämie: funikuläre Myelose (Hinterstränge, Pyramidenbahn), Polyneuropathie, kognitive Störungen bis Demenz, Depression – teils irreversibel.","risiko":"Vegane Ernährung ohne Supplement (DGE: Präparat notwendig), Autoimmungastritis (perniziöse Anämie), atrophische H.-pylori-Gastritis, Gastrektomie und bariatrische OP, Ileumresektion, Morbus Crohn, exokrine Pankreasinsuffizienz, bakterielle Fehlbesiedlung, höheres Alter, gestillte Säuglinge veganer Mütter. Medikamente: Metformin, PPI und H2-Blocker, Colchicin; Lachgas inaktiviert die Methioninsynthase.","ueberdosis":"Keine Toxizität bekannt; EFSA hat keinen UL abgeleitet. Ein erhöhtes Serum-B12 ohne Supplementierung kann auf Lebererkrankungen, myeloproliferative Neoplasien oder solide Tumoren hinweisen (Haptocorrin ↑).","quellen":"Nur tierische Lebensmittel liefern relevante Mengen: Leber, Fleisch, Fisch, Eier, Milchprodukte. Algen (Nori), Shiitake und Sauerkraut enthalten überwiegend für den Menschen nicht verfügbare Formen (DGE); die IF-abhängige Aufnahme pro Mahlzeit ist begrenzt.","labor":"Gesamt-B12 im Serum ist wenig sensitiv, da überwiegend an Haptocorrin gebunden; Holotranscobalamin sinkt früh, Methylmalonsäure ist funktionell spezifisch, aber bei Niereninsuffizienz falsch erhöht, Homocystein unspezifisch. Intrinsic-Factor-Antikörper sind hochspezifisch für die perniziöse Anämie; Folsäure kann die Anämie normalisieren und den Mangel maskieren.","interaktion":"Funktionelle Kopplung mit Folat (Methylfolat-Falle, Maskierung der Anämie durch Folsäure). Metformin (calciumabhängige Ileumaufnahme), PPI/H2-Blocker (verminderte Freisetzung aus Nahrungsproteinen), Colchicin und Lachgas (Oxidation von Cob(I)alamin) beeinträchtigen den Status.","ref":{"wert":"4,0 µg/Tag (Erwachsene, m und w)","art":"Schätzwert","quelle":"https://www.dge.de/wissenschaft/referenzwerte/vitamin-b12/","stand":"2018"},"ul":null,"links":{"dis":["vitamin_b12_mangel","vitamin_b12_mangelanaemie","funikulaere_myelose","autoimmungastritis","helicobacter_gastritis","morbus_crohn","kurzdarmsyndrom","exokrine_pankreasinsuffizienz","diabetes_typ2","adipositas","depression"],"path":["methylierungszyklus","citratzyklus"]},"mcq":[{"q":"Eine Patientin mit CKD Stadium 4 hat eine erhöhte Methylmalonsäure bei normalem Holotranscobalamin. Wie ist das zu werten?","a":"MMA ist bei eingeschränkter Nierenfunktion falsch erhöht und hier wenig aussagekräftig","w":["Bestätigter B12-Mangel, da MMA der spezifischste Marker überhaupt ist","Folatmangel, da MMA bei fehlendem 5-Methyl-THF in den Mitochondrien kompensatorisch ansteigt","Hinweis auf B6-Mangel, da die Methylmalonyl-CoA-Mutase PLP-abhängig ist"],"why":"MMA wird renal eliminiert und steigt bei Niereninsuffizienz unabhängig vom B12-Status; deshalb Kombination mit Holo-TC."},{"q":"Ein Diabetiker unter langjährigem Metformin entwickelt Parästhesien. Welcher Mechanismus erklärt einen B12-Mangel am ehesten?","a":"Störung der calciumabhängigen Aufnahme des IF-B12-Komplexes im Ileum","w":["Hemmung der Intrinsic-Factor-Sekretion der Parietalzellen","Verdrängung von B12 aus der Bindung an Transcobalamin im Plasma durch Metformin","Steigerung der renalen B12-Ausscheidung durch Glukosurie"],"why":"Die Cubilin-vermittelte Aufnahme ist calciumabhängig und wird durch Metformin beeinträchtigt; eine Neuropathie darf daher nicht vorschnell als diabetisch gewertet werden."},{"q":"Nach Lachgasexposition entwickelt ein Patient mit grenzwertigem B12-Status rasch eine funikuläre Myelose. Welcher Mechanismus liegt zugrunde?","a":"Oxidation von Cob(I)alamin mit Inaktivierung der Methioninsynthase","w":["Hemmung des Intrinsic Factor durch Stickoxide im Magen","Blockade der Methylmalonyl-CoA-Mutase durch Nitrosylierung","Steigerung der biliären B12-Ausscheidung durch Lachgas"],"why":"N₂O oxidiert das Cobaltzentrum; die Methioninsynthase fällt aus und die SAM-abhängige Myelinmethylierung bricht ein – relevant auch bei Freizeitkonsum."}]},{"id":"vitamin_c","name":"Vitamin C (Ascorbinsäure)","gruppe":"Wasserlösliche Vitamine","aktiveForm":"L-Ascorbinsäure (Ascorbat); oxidierte Form Dehydroascorbinsäure, intrazellulär recycelt","funktion":"Elektronendonor für Fe²⁺/2-Oxoglutarat-abhängige Dioxygenasen und kupferhaltige Monooxygenasen: Prolyl- und Lysylhydroxylasen (Kollagenstabilität), Carnitinsynthese, HIF-Prolylhydroxylasen, Dopamin-β-Hydroxylase (Noradrenalin) und Peptidylglycin-α-amidierende Monooxygenase. Wasserlösliches Antioxidans, regeneriert α-Tocopherol und reduziert Nahrungseisen (Fe³⁺ → Fe²⁺).","aufnahme":"Aktive Aufnahme über die natriumabhängigen Transporter SVCT1 (Darm, Niere) und SVCT2 (Gewebe), Dehydroascorbinsäure über GLUT; die relative Absorption sinkt bei hohen Einzeldosen. Die renale Rückresorption ist sättigbar, Plasmaspiegel plateauieren und Überschuss wird ausgeschieden; hohe Gewebekonzentrationen in Nebenniere, Hypophyse und Leukozyten.","mangel":"Früh: Müdigkeit, Reizbarkeit, Gelenk- und Muskelschmerzen. Skorbut: perifollikuläre Blutungen, Korkenzieherhaare, Hyperkeratose, Zahnfleischschwellung und -bluten, Ekchymosen, Wundheilungsstörung, Anämie; bei Kindern subperiostale Blutungen (Möller-Barlow-Krankheit).","risiko":"Sehr einseitige Kost mit wenig Obst und Gemüse (Alkoholabhängigkeit, Isolation im Alter, selektives Essverhalten), Rauchen (erhöhter Umsatz – DGE: höhere Zufuhrempfehlung), Dialyse, Malabsorption, schwere Erkrankung und Sepsis.","ueberdosis":"Geringe Toxizität; hohe Dosen verursachen osmotische Diarrhö und steigern die Oxalatausscheidung (Calciumoxalatsteine, v. a. bei Männern und Niereninsuffizienz). Bei G6PD-Mangel kann hochdosiertes i.v.-Vitamin C eine Hämolyse auslösen, bei Hämochromatose verstärkt es die Eisenaufnahme; EFSA hat keinen UL abgeleitet.","quellen":"Paprika, Brokkoli und Kohlarten, Zitrusfrüchte, Beeren (Sanddorn, schwarze Johannisbeere), Kiwi, Kartoffeln. Hitze-, sauerstoff- und lichtempfindlich, Verluste durch Lagerung und Kochen.","labor":"Plasma-Ascorbat spiegelt die kurzfristige Zufuhr, Leukozyten-Ascorbat eher den Gewebestatus. Die Probe muss rasch stabilisiert, gekühlt und lichtgeschützt verarbeitet werden, sonst falsch niedrig; in der Akutphase sinkt Plasma-Ascorbat, hohe Spiegel stören redoxbasierte Tests (manche Glukosemessgeräte, Urinteststreifen).","interaktion":"Steigert die Nicht-Hämeisen-Absorption (Reduktion zu Fe²⁺, Chelatbildung gegen Phytat und Polyphenole) und regeneriert Vitamin E. Rauchen erhöht den Bedarf; hohe Dosen können Oxalatsteine fördern und Laborwerte verfälschen.","ref":{"wert":"m 110 / w 95 mg/Tag (Erwachsene); Raucher m 155 / w 135 mg/Tag","art":"Empfehlung","quelle":"https://www.dge.de/wissenschaft/referenzwerte/vitamin-c/","stand":"2015"},"ul":null,"links":{"dis":["skorbut","eisenmangelanaemie","haemochromatose","nephrolithiasis","g6pd_mangel","alkoholabhaengigkeit","sepsis"],"path":["eisen"]},"mcq":[{"q":"Ein Mann mit Alkoholabhängigkeit hat Zahnfleischbluten, perifollikuläre Petechien und Korkenzieherhaare bei normaler Thrombozytenzahl und Gerinnung. Welcher Mechanismus erklärt die Blutungen?","a":"Instabiles Kollagen der Gefäßwand durch fehlende Prolylhydroxylierung","w":["Fehlende γ-Carboxylierung der Gerinnungsfaktoren in der Leber","Verminderte Thrombozytenbildung bei megaloblastärer Hämatopoese","Gesteigerte Fibrinolyse durch alkoholinduzierte Plasminogenaktivierung im Gefäßendothel"],"why":"Ascorbat hält das Eisen der Prolyl- und Lysylhydroxylasen reduziert; untervernetztes Kollagen macht Kapillaren fragil, während Gerinnung und Thrombozyten normal sind."},{"q":"Warum ist Plasma-Ascorbat bei einem septischen Intensivpatienten nur eingeschränkt verwertbar?","a":"Es sinkt in der Akutphase und ist präanalytisch stark oxidationsempfindlich","w":["Es wird in der Sepsis vermehrt an Albumin gebunden und nicht erfasst","Es steigt in der Sepsis durch ACTH-vermittelte Freisetzung aus der Nebenniere stark an","Es ist nur im Urin messbar, da Ascorbat nicht im Plasma zirkuliert"],"why":"Entzündung und oxidativer Stress senken die Spiegel; ohne rasche Stabilisierung oxidiert Ascorbat in vitro und wird falsch niedrig gemessen."},{"q":"Ein Patient mit Hämochromatose fragt nach einem hochdosierten Vitamin-C-Präparat zu den Mahlzeiten. Warum ist davon abzuraten?","a":"Ascorbat reduziert Fe³⁺ zu Fe²⁺ und steigert die DMT1-vermittelte Nicht-Hämeisen-Aufnahme","w":["Ascorbat hemmt die Hepcidinwirkung direkt am Ferroportin der Enterozyten","Ascorbat steigert die Transferrinsynthese und damit die Eisenspeicherung","Ascorbat steigert vor allem die Hämeisenaufnahme über den Transporter HCP1 im terminalen Ileum"],"why":"Ascorbat wirkt im Darmlumen als Reduktionsmittel und Chelator; bei fehlender Hepcidinbremse verstärkt dies die Eisenüberladung."}]},{"id":"calcium","name":"Calcium","gruppe":"Mengenelemente","aktiveForm":"Ionisiertes Ca²⁺ (etwa die Hälfte des Serumcalciums, Rest v. a. albumingebunden oder komplexiert); 99 % des Körpercalciums als Hydroxylapatit im Skelett","funktion":"Strukturbaustein von Knochen und Zähnen; Ca²⁺ ist Second Messenger (Calmodulin, Proteinkinase C), löst Muskelkontraktion (Troponin C) und Exozytose/Transmitterfreisetzung aus, ist Gerinnungsfaktor IV und stabilisiert die Erregbarkeit von Nerven- und Muskelmembranen.","aufnahme":"Aktiv-transzellulär im Duodenum (TRPV6 → Calbindin-D9k → PMCA1b/NCX1, calcitriolabhängig, dominiert bei niedriger Zufuhr) und passiv-parazellulär im gesamten Dünndarm (bei hoher Zufuhr); die fraktionelle Absorption steigt adaptiv bei geringer Zufuhr. Regulation über PTH (Knochenresorption, distal-tubuläre Rückresorption, Calcitriolbildung), Calcitriol und den Calcium-sensing-Rezeptor (CaSR) in Nebenschilddrüse und Niere.","mangel":"Akute Hypokalzämie: periorale und akrale Parästhesien, Tetanie, Chvostek- und Trousseau-Zeichen, Laryngospasmus, Krampfanfälle, QT-Verlängerung. Chronisch niedrige Zufuhr: sekundärer Hyperparathyreoidismus mit Knochenmasseverlust (Osteoporose; mit Vitamin-D-Mangel Rachitis/Osteomalazie), wobei der Serumspiegel lange normal bleibt.","risiko":"Geringe Milchproduktzufuhr ohne Ersatz (vegan, Laktoseintoleranz), Vitamin-D-Mangel, höheres Alter, Postmenopause, Malabsorption (Zöliakie, Kurzdarm, bariatrische OP), Hypoparathyreoidismus (z. B. nach Schilddrüsen-OP), Hypomagnesiämie, CKD, akute Pankreatitis. Medikamente: Schleifendiuretika, Glukokortikoide, Bisphosphonate/Denosumab (Hypokalzämie), PPI (schlechtere Löslichkeit von Calciumcarbonat).","ueberdosis":"Hyperkalzämie: Polyurie, Exsikkose, Obstipation, Übelkeit, Muskelschwäche, Verwirrtheit, verkürztes QT, Nephrokalzinose; mit gleichzeitiger Alkalizufuhr Milch-Alkali-Syndrom (metabolische Alkalose, Nierenversagen). Supplemente – nicht Nahrungscalcium – erhöhen das Nierensteinrisiko; ein erhöhtes kardiovaskuläres Risiko durch Supplemente wird diskutiert.","quellen":"Milch und Milchprodukte (Hartkäse besonders reich), calciumreiche Mineralwässer, oxalatarme grüne Gemüse (Grünkohl, Brokkoli), Mandeln, Sesam, mit Calciumsulfat hergestellter Tofu. Oxalat (Spinat, Rhabarber) und Phytat senken die Bioverfügbarkeit stark.","labor":"Gesamtcalcium hängt vom Albumin ab (Korrekturformeln ungenau); bei Hypalbuminämie, Säure-Basen-Störungen und kritisch Kranken ionisiertes Calcium messen – Alkalose senkt, Azidose erhöht das freie Ca²⁺. Der Serumspiegel sagt nichts über Zufuhr oder Knochenbilanz; Bewertung mit PTH, 25-OH-D, Phosphat, Magnesium, Kreatinin und ggf. Urin-Calcium.","interaktion":"Calcium hemmt die Aufnahme von Eisen und Zink sowie von Tetrazyklinen, Fluorchinolonen, Levothyroxin und Bisphosphonaten (zeitlich versetzt einnehmen). Thiazide senken, Schleifendiuretika steigern die Calciurie, hohe Natrium- und Proteinzufuhr erhöhen sie; Calcium bindet Oxalat im Darm und senkt so die Oxalatabsorption.","ref":{"wert":"1000 mg/Tag (Erwachsene ab 19 J., m und w)","art":"Empfehlung","quelle":"https://www.dge.de/wissenschaft/referenzwerte/calcium/","stand":"2013"},"ul":{"wert":"2500 mg/Tag","art":"UL","quelle":"https://www.efsa.europa.eu/sites/default/files/2024-05/ul-summary-report.pdf (EFSA: Overview on Tolerable Upper Intake Levels, Version 11 (August 2025); Grundlage: EFSA NDA Panel 2012)"},"links":{"dis":["hypokalzaemie","hyperkalzaemie","osteoporose","osteomalazie","rachitis","primaerer_hyperparathyreoidismus","sekundaerer_hyperparathyreoidismus","hypoparathyreoidismus","nephrolithiasis","laktoseintoleranz","chronische_nierenkrankheit"],"path":["vitamin-d"]},"mcq":[{"q":"Eine hyperventilierende Patientin entwickelt Pfötchenstellung und periorale Parästhesien bei normalem Gesamtcalcium. Wie ist das zu erklären?","a":"Die respiratorische Alkalose erhöht die Albuminbindung und senkt das ionisierte Ca²⁺","w":["Hyperventilation steigert die renale Calciumausscheidung bereits binnen weniger Minuten massiv","Die Alkalose hemmt die PTH-Freisetzung und senkt das Gesamtcalcium","Die CO₂-Abatmung fällt Calcium als Calciumcarbonat im Plasma aus"],"why":"Bei steigendem pH gibt Albumin H⁺ ab und bindet mehr Ca²⁺; das Gesamtcalcium bleibt gleich, das freie sinkt."},{"q":"Warum führt die Kombination aus hochdosiertem Calciumcarbonat und weiteren Antazida mitunter zu Nierenversagen?","a":"Milch-Alkali-Syndrom: Hyperkalzämie, Alkalose und sinkende GFR verstärken sich gegenseitig","w":["Calciumcarbonat fällt in den distalen Nierentubuli als Struvit aus und verstopft sie mechanisch","Antazida hemmen die PTH-Sekretion und verhindern dadurch jede Calciurie","Calciumcarbonat wird renal zu Calciumoxalat umgebaut und kristallisiert"],"why":"Hyperkalzämie verursacht Volumenmangel und senkt die GFR (Bicarbonatretention); die Alkalose steigert ihrerseits die tubuläre Calciumrückresorption – ein Teufelskreis."},{"q":"Bei welcher Konstellation ist die Calciumabsorption aus Calciumcarbonat besonders vermindert, aus Calciumcitrat aber kaum?","a":"Achlorhydrie (PPI, atrophische Gastritis) bei Nüchterneinnahme","w":["Einnahme zusammen mit einer fettreichen Hauptmahlzeit","Hohe Calcitriolspiegel mit gesteigerter TRPV6-Expression","Gleichzeitige Zufuhr von Laktose aus Milchprodukten"],"why":"Carbonat braucht Säure zur Lösung, eine Mahlzeit kompensiert dies teilweise; Citrat ist säureunabhängig löslich."}]},{"id":"magnesium","name":"Magnesium","gruppe":"Mengenelemente","aktiveForm":"Freies Mg²⁺; intrazellulär überwiegend als Mg-ATP-Komplex; gut die Hälfte des Körpermagnesiums im Knochen, unter 1 % im Serum","funktion":"Kofaktor von über 300 Enzymen, insbesondere aller ATP-abhängigen Reaktionen (Mg-ATP ist das eigentliche Substrat von Kinasen und ATPasen wie der Na⁺/K⁺-ATPase), sowie von Nukleinsäurepolymerasen und Proteinsynthese. Physiologischer Calciumantagonist (NMDA-Rezeptor-Block, L-Typ-Calciumkanäle), stabilisiert Membranpotenzial und Herzrhythmus und ist für PTH-Sekretion und -Wirkung nötig.","aufnahme":"Absorption parazellulär (Hauptweg bei normaler Zufuhr) und transzellulär über TRPM6/7 im distalen Dünndarm und Kolon; die fraktionelle Absorption steigt bei geringer Zufuhr. Die Niere ist der Hauptregulator: Rückresorption überwiegend parazellulär im dicken aufsteigenden Henle-Schenkel (Claudin-16/19), Feinregulation im distalen Konvolut über TRPM6 (EGF-abhängig).","mangel":"Neuromuskuläre Übererregbarkeit (Tremor, Krämpfe, Tetanie, Chvostek/Trousseau), Krampfanfälle, Herzrhythmusstörungen (Torsade de pointes, Vorhofflimmern), Apathie. Typische Begleitstörungen: refraktäre Hypokaliämie (renaler K⁺-Verlust über ROMK) und Hypokalzämie (verminderte PTH-Sekretion und PTH-Resistenz).","risiko":"Alkoholabhängigkeit, chronische Diarrhö, Malabsorption, Kurzdarm, Refeeding, schlecht eingestellter Diabetes (osmotische Diurese), Gitelman- und Bartter-Syndrom. Medikamente: PPI (gestörte TRPM6/7-Aufnahme), Schleifen- und Thiaziddiuretika, Calcineurininhibitoren, Cisplatin, Aminoglykoside, Amphotericin B, EGFR-Antikörper (Cetuximab).","ueberdosis":"Über Lebensmittel bei intakter Niere keine Hypermagnesiämie; der EFSA-UL gilt nur für leicht dissoziierbare Salze in Supplementen und Zusätzen, kritischer Effekt ist osmotische Diarrhö. Hypermagnesiämie (v. a. Niereninsuffizienz, magnesiumhaltige Laxanzien/Antazida, i.v.-Gabe) führt zu Reflexverlust, Hypotonie, Bradykardie, Atemdepression bis Herzstillstand.","quellen":"Vollkornprodukte, Hülsenfrüchte, Nüsse und Samen (Kürbiskerne), grünes Blattgemüse (Chlorophyll), Kakao, magnesiumreiche Mineralwässer. Phytat sowie sehr hohe Calcium- und Phosphatzufuhr können die Aufnahme mindern.","labor":"Serum-Mg erfasst unter 1 % des Körperbestands und kann trotz intrazellulärem Mangel normal sein; Hämolyse verfälscht falsch hoch. Ergänzend fraktionelle Mg-Ausscheidung im Urin (renaler vs. extrarenaler Verlust) und Belastungstest (Retention); Erythrozyten-Mg ist schlecht standardisiert.","interaktion":"Mg bildet Komplexe mit Tetrazyklinen, Fluorchinolonen, Bisphosphonaten und Levothyroxin (zeitlich versetzt einnehmen). PPI, Diuretika, Calcineurininhibitoren und Cisplatin senken den Status; Mg-Mangel verschlechtert Hypokaliämie, Hypokalzämie und Digitalistoxizität, sehr hohe Zinkdosen mindern die Mg-Absorption.","ref":{"wert":"m 350 / w 300 mg/Tag (Erwachsene)","art":"Schätzwert","quelle":"https://www.dge.de/wissenschaft/referenzwerte/magnesium/","stand":"2021"},"ul":{"wert":"250 mg/Tag (nur leicht dissoziierbare Mg-Salze und MgO in Supplementen, Wasser und angereicherten Lebensmitteln; nicht Nahrungsmagnesium)","art":"UL","quelle":"https://www.efsa.europa.eu/sites/default/files/2024-05/ul-summary-report.pdf (EFSA: Overview on Tolerable Upper Intake Levels, Version 11 (August 2025); Grundlage: SCF 2001)"},"links":{"dis":["magnesiummangel","hypokalzaemie","hypokaliaemie","hypoparathyreoidismus","ventrikulaere_tachykardie","long_qt_syndrom","alkoholabhaengigkeit","refeeding_syndrom","praeeklampsie","chronische_nierenkrankheit"],"path":["glykolyse"]},"mcq":[{"q":"Eine Hypokaliämie steigt trotz konsequenter Kaliumsubstitution nicht an. Welcher Begleitbefund erklärt die Refraktärität am ehesten?","a":"Hypomagnesiämie mit enthemmter K⁺-Sekretion über ROMK im distalen Nephron","w":["Hypokalzämie mit verminderter Na⁺/K⁺-ATPase-Expression im Skelettmuskel","Hypophosphatämie mit gesteigerter Kaliumverschiebung in die Erythrozyten","Hypernatriämie mit kompetitiver Hemmung der Kaliumaufnahme im Darm"],"why":"Intrazelluläres Mg²⁺ blockiert ROMK; bei Mg-Mangel geht Kalium renal verloren, bis Magnesium ausgeglichen ist."},{"q":"Ein Patient unter langjähriger PPI-Therapie hat Tetanie, Hypokalzämie und ein inadäquat niedriges PTH. Was ist der wahrscheinlichste Mechanismus?","a":"PPI-bedingte Hypomagnesiämie hemmt PTH-Sekretion und -Wirkung","w":["PPI blockieren direkt den Calcium-sensing-Rezeptor der Nebenschilddrüse","PPI steigern die renale Calciumausscheidung über Claudin-16","PPI verursachen einen Vitamin-D-Mangel durch Hemmung von CYP2R1"],"why":"PPI stören die TRPM6/7-vermittelte intestinale Mg-Aufnahme; schwerer Mg-Mangel blockiert die PTH-Freisetzung, die Hypokalzämie bessert sich erst nach Mg-Ausgleich."},{"q":"Welches klinische Zeichen ist unter i.v.-Magnesiumtherapie (z. B. bei Präeklampsie) das früheste Warnsignal einer Hypermagnesiämie?","a":"Abschwächung bzw. Verlust der Muskeleigenreflexe","w":["Positives Chvostek-Zeichen mit Karpopedalspasmen","Tachykardie mit verkürzter QT-Zeit im EKG","Hyperreflexie mit generalisiertem Tremor"],"why":"Mg²⁺ hemmt die Acetylcholinfreisetzung an der motorischen Endplatte; der Reflexverlust geht Atemdepression und Herzstillstand voraus."}]},{"id":"phosphor","name":"Phosphor (Phosphat)","gruppe":"Mengenelemente","aktiveForm":"Anorganisches Phosphat (HPO₄²⁻/H₂PO₄⁻); organisch gebunden in ATP, Kreatinphosphat, 2,3-BPG, Nukleinsäuren und Phospholipiden; Großteil im Skelett als Hydroxylapatit","funktion":"Bestandteil von Hydroxylapatit, Nukleinsäuren und Membranphospholipiden; energiereiche Phosphatbindungen (ATP, Kreatinphosphat), Signaltransduktion durch Phosphorylierung, Puffer in Zelle und Urin. 2,3-Bisphosphoglycerat reguliert die Sauerstoffabgabe des Hämoglobins.","aufnahme":"Absorption parazellulär und transzellulär über NaPi-IIb (calcitriolabhängig); anorganische Zusatzphosphate werden nahezu vollständig, Phytatphosphor mangels intestinaler Phytase nur gering aufgenommen. Renale Regulation über NaPi-IIa/IIc im proximalen Tubulus, gehemmt durch PTH und FGF23 (mit Klotho); FGF23 senkt zusätzlich die Calcitriolbildung.","mangel":"Ernährungsbedingt selten (DGE). Hypophosphatämie: Muskelschwäche bis Rhabdomyolyse, Ateminsuffizienz, Herzinsuffizienz, Hämolyse, Linksverschiebung der O₂-Bindungskurve (2,3-BPG ↓), Verwirrtheit; chronisch Rachitis/Osteomalazie (z. B. FGF23-vermittelt bei X-chromosomaler Hypophosphatämie).","risiko":"Refeeding-Syndrom (insulinvermittelte Verschiebung nach intrazellulär – Leitbefund), Alkoholabhängigkeit, Therapie der diabetischen Ketoazidose, respiratorische Alkalose, primärer Hyperparathyreoidismus, Frühgeborene. Medikamente: phosphatbindende Antazida, i.v.-Eisencarboxymaltose (FGF23-Anstieg), tubulotoxische Substanzen (z. B. Tenofovir, Fanconi-Syndrom).","ueberdosis":"Hyperphosphatämie v. a. bei Niereninsuffizienz: sekundärer Hyperparathyreoidismus, Gefäß- und Weichteilverkalkung (CKD-MBD); akut nach phosphathaltigen Abführmitteln (akute Phosphatnephropathie) und Tumorlyse. Hohe Zufuhr über Zusatzphosphate gilt als ungünstig (DGE); EFSA hat keinen UL abgeleitet.","quellen":"Milchprodukte (besonders Schmelzkäse), Fleisch, Fisch, Hülsenfrüchte, Nüsse, Samen, Vollkorn. Phosphatzusätze (E 338–E 452, Schmelzsalze, Backtriebmittel, phosphorsäurehaltige Colagetränke) erhöhen die Zufuhr und sind nahezu vollständig verfügbar.","labor":"Serumphosphat zeigt zirkadiane und postprandiale Schwankungen (nüchtern messen) und sinkt durch Verschiebung nach intrazellulär (Alkalose, Insulin/Glukose); Hämolyse erhöht falsch. Renale Abklärung über die tubuläre Phosphatschwelle (TmP/GFR), ergänzend PTH, FGF23, Calcitriol und AP.","interaktion":"Calcium-, Aluminium-, Magnesium- und Lanthanverbindungen binden Phosphat im Darm (Prinzip der Phosphatbinder bei CKD); Calcitriol steigert die Absorption. Das Calcium-Phosphor-Verhältnis der Zufuhr beeinflusst PTH und Knochenstoffwechsel (DGE); i.v.-Eisencarboxymaltose induziert renale Phosphatverluste.","ref":{"wert":"550 mg/Tag (Erwachsene, m und w)","art":"Schätzwert","quelle":"https://www.dge.de/wissenschaft/referenzwerte/phosphor/","stand":"2022"},"ul":null,"links":{"dis":["refeeding_syndrom","anorexia_nervosa","chronische_nierenkrankheit","sekundaerer_hyperparathyreoidismus","primaerer_hyperparathyreoidismus","rachitis","osteomalazie","diabetische_ketoazidose","rhabdomyolyse"],"path":["vitamin-d","glykolyse","atmungskette"]},"mcq":[{"q":"Am dritten Tag der Wiederernährung bei Anorexia nervosa treten Muskelschwäche, Dyspnoe und Verwirrtheit auf. Welcher Laborwert ist am ehesten führend verändert?","a":"Phosphat, durch insulinvermittelte Verschiebung nach intrazellulär","w":["Natrium, durch vermehrte ADH-Freisetzung unter Wiederernährung","Calcium, durch PTH-Suppression unter Kohlenhydratzufuhr","Chlorid, durch renale Retention bei gesteigerter Glukoneogenese"],"why":"Insulin treibt Phosphat für Glykolyse und ATP-Bildung in die Zellen; Hypophosphatämie ist Leitbefund des Refeeding-Syndroms, oft mit Hypokaliämie, Hypomagnesiämie und Thiaminmangel."},{"q":"Nach i.v.-Eisencarboxymaltose entwickelt eine Patientin Knochenschmerzen und eine Hypophosphatämie bei erhöhtem PTH. Welcher Mechanismus erklärt den Phosphatverlust?","a":"Anstieg von intaktem FGF23 hemmt renale NaPi-IIa/IIc und die Calcitriolbildung","w":["Eisen bindet Phosphat im Plasma und fällt als Eisenphosphat aus","Carboxymaltose hemmt direkt die intestinale NaPi-IIb-Expression","Eisen steigert die Aktivität der alkalischen Phosphatase und damit den Phosphatverbrauch im Knochen"],"why":"Die Carboxymaltose hemmt die FGF23-Spaltung; Phosphaturie und Calcitriolmangel verursachen sekundären Hyperparathyreoidismus und im Extremfall Osteomalazie."},{"q":"Warum gelten Zusatzphosphate in verarbeiteten Lebensmitteln bei CKD als problematischer als natürliches Phosphat aus Hülsenfrüchten?","a":"Anorganische Zusatzphosphate werden nahezu vollständig, Phytatphosphor nur gering resorbiert","w":["Zusatzphosphate werden renal schneller ausgeschieden als Phytatphosphor","Phytatphosphor wird im Kolon durch körpereigene Phytase nahezu vollständig freigesetzt und resorbiert","Zusatzphosphate hemmen direkt die FGF23-Bildung in den Osteozyten"],"why":"Der Mensch besitzt kaum intestinale Phytase, zugesetzte Salze sind dagegen frei verfügbar – Phosphat aus Pflanzen belastet die Bilanz weniger."}]},{"id":"kalium","name":"Kalium","gruppe":"Mengenelemente","aktiveForm":"K⁺ (Hauptkation des Intrazellulärraums, rund 98 % intrazellulär)","funktion":"Bestimmt über den von der Na⁺/K⁺-ATPase aufgebauten Gradienten das Ruhemembranpotenzial und damit die Erregbarkeit von Nerven-, Skelett- und Herzmuskelzellen. Beteiligt an Zellvolumen-, Säure-Basen- und Blutdruckregulation sowie an Insulinsekretion (KATP-Kanal) und Proteinsynthese.","aufnahme":"Weitgehend vollständige Absorption im Dünndarm. Die renale Ausscheidung wird über Aldosteron und den distalen Fluss gesteuert (ENaC-getriebene K⁺-Sekretion über ROMK und BK-Kanäle); Insulin, β2-Agonisten und Alkalose verschieben K⁺ nach intrazellulär, das Kolon sezerniert K⁺ adaptiv bei Niereninsuffizienz.","mangel":"Hypokaliämie: Muskelschwäche, Obstipation bis paralytischer Ileus, Rhabdomyolyse; EKG mit abgeflachter T-Welle, U-Welle, ST-Senkung und Arrhythmien (v. a. unter Digitalis); renal nephrogener Diabetes insipidus und metabolische Alkalose. Eine dauerhaft geringe Zufuhr ist mit höherem Blutdruck und Schlaganfallrisiko assoziiert.","risiko":"Erbrechen, Diarrhö, Laxanzienabusus (Essstörungen), Thiazid- und Schleifendiuretika, primärer Hyperaldosteronismus, Lakritzkonsum (11β-HSD2-Hemmung), Cushing-Syndrom, Hypomagnesiämie; Verschiebung nach intrazellulär durch Insulin (DKA-Therapie, Refeeding) und β2-Agonisten.","ueberdosis":"Bei intakter Nierenfunktion ernährungsbedingt kaum; Hyperkaliämie-Risiko bei CKD, Hypoaldosteronismus und Morbus Addison sowie unter RAAS-Blockern, Spironolacton/Eplerenon, Amilorid, Trimethoprim, NSAR, Calcineurininhibitoren und Heparin – besonders mit Kaliumchlorid-Salzersatz. Folgen: Schwäche, Parästhesien, spitze T-Wellen, QRS-Verbreiterung bis Kammerflimmern; EFSA hat keinen UL abgeleitet.","quellen":"Gemüse, Kartoffeln, Hülsenfrüchte, Obst (Aprikosen, Bananen, Trockenobst), Nüsse, Dinkel- und Roggenmehl (DGE), Kaffee. Kalium geht beim Wässern und Kochen ins Wasser über (genutzt bei CKD); Kaliumchlorid in Diätsalzen.","labor":"Pseudohyperkaliämie durch Hämolyse, Faustschluss, langes Stauen, Thrombozytose/Leukozytose oder gekühlten Transport (Hemmung der Na⁺/K⁺-ATPase) – unplausible Werte z. B. per Blutgasanalyse kontrollieren. Abklärung von Verlusten über Urin-K⁺ bzw. K⁺/Kreatinin-Quotient, Säure-Basen-Status, Renin/Aldosteron und Magnesium.","interaktion":"RAAS-Blocker, kaliumsparende Diuretika, Trimethoprim, NSAR, Heparin und Calcineurininhibitoren erhöhen das Serumkalium; Thiazid- und Schleifendiuretika, Glukokortikoide, Insulin und β2-Agonisten senken es. Hypokaliämie steigert die Digitalistoxizität, Magnesiummangel macht sie therapierefraktär.","ref":{"wert":"4000 mg/Tag (Erwachsene, m und w)","art":"Schätzwert","quelle":"https://www.dge.de/wissenschaft/referenzwerte/kalium/","stand":"2016"},"ul":null,"links":{"dis":["hypokaliaemie","hyperkaliaemie","arterielle_hypertonie","chronische_nierenkrankheit","conn_syndrom","pseudohyperaldosteronismus_lakritz","morbus_addison","diabetische_ketoazidose","bulimia_nervosa","refeeding_syndrom"],"path":["raas"]},"mcq":[{"q":"Ein Patient mit Hypertonie, Hypokaliämie und metabolischer Alkalose hat supprimiertes Renin und supprimiertes Aldosteron. Was ist die wahrscheinlichste ernährungsassoziierte Ursache?","a":"Hoher Lakritzkonsum mit Hemmung der 11β-HSD2 durch Glycyrrhetinsäure","w":["Aldosteronproduzierendes Adenom der Nebennierenrinde","Exzessive Kaliumzufuhr über Diätsalz mit Kaliumchlorid","Chronischer Laxanzienabusus mit hohen intestinalen Kaliumverlusten über den Stuhl"],"why":"Cortisol wird nicht mehr zu Cortison inaktiviert und aktiviert den Mineralokortikoidrezeptor – Bild eines Hyperaldosteronismus bei niedrigem Renin und Aldosteron."},{"q":"Routinemäßig wird Kalium 6,4 mmol/l gemessen; EKG unauffällig, die Probe war lange gestaut und gekühlt transportiert. Wie ist vorzugehen?","a":"Pseudohyperkaliämie erwägen und umgehend mit korrekter Präanalytik nachmessen","w":["Den Wert als gesichert werten und die Kaliumzufuhr dauerhaft drastisch senken","Den Wert als Beleg für einen Hypoaldosteronismus werten und weiter abklären","Den Wert ignorieren, da Kalium bei normalem EKG nie gefährlich erhöht ist"],"why":"Hämolyse, Stauung und Kühlung setzen K⁺ in vitro frei; ein normales EKG stützt den Verdacht, schließt eine echte Hyperkaliämie aber nicht aus – daher sofortige Kontrolle (z. B. Blutgas)."},{"q":"Warum führt chronisches Erbrechen zu einer Hypokaliämie, obwohl Magensaft relativ kaliumarm ist?","a":"Volumenmangel und Alkalose steigern Aldosteron und den distalen K⁺-Verlust mit Bicarbonat","w":["Magensaft enthält so viel Kalium, dass die direkten Verluste überwiegen","Erbrechen hemmt die intestinale Kaliumaufnahme im Duodenum vollständig","Der HCl-Verlust aktiviert die renale H⁺/K⁺-ATPase der Schaltzellen zur aktiven Kaliumsekretion"],"why":"Hypovolämie aktiviert das RAAS, filtriertes Bicarbonat erhöht den distalen Fluss mit schlecht resorbierbarem Anion – entscheidend ist der renale K⁺-Verlust."}]},{"id":"natrium","name":"Natrium","gruppe":"Mengenelemente","aktiveForm":"Na⁺ (Hauptkation des Extrazellulärraums)","funktion":"Bestimmt die extrazelluläre Osmolalität und damit Extrazellulärvolumen und Blutdruck. Der Na⁺-Gradient (Na⁺/K⁺-ATPase) treibt Aktionspotenziale und sekundär aktive Transporte (SGLT1, Aminosäuretransporter, Na⁺/H⁺-Austauscher).","aufnahme":"Nahezu vollständige Absorption, u. a. glukosegekoppelt über SGLT1 (Grundlage der oralen Rehydratation), über NHE3 und im Kolon über ENaC. Renale Ausscheidung über RAAS (Aldosteron → ENaC), natriuretische Peptide, Sympathikus und Druckdiurese; die Serumkonzentration wird über ADH und Durst (Wasserbilanz) geregelt.","mangel":"Ernährungsbedingter Natriummangel ist selten; Verluste führen zu Hypovolämie (Hypotonie, Tachykardie, prärenales Nierenversagen). Hyponatriämie ist meist eine Störung der Wasserbilanz: Übelkeit, Kopfschmerz, Verwirrtheit, Stürze, Krampfanfälle, Hirnödem; zu rasche Korrektur chronischer Hyponatriämie riskiert osmotische Demyelinisierung.","risiko":"Hyponatriämie: SIADH (SSRI, Carbamazepin/Oxcarbazepin, Tumoren, Pneumonie), Thiazide, Herzinsuffizienz, Leberzirrhose, Nebennierenrindeninsuffizienz, Hypothyreose, hohe Trinkmenge bei geringer Solutzufuhr (Tea-and-Toast, Bierpotomanie), Ausdauersport. Salzverluste über Schweiß (Mukoviszidose), Erbrechen, Diarrhö und zerebrales Salzverlustsyndrom.","ueberdosis":"Hohe Kochsalzzufuhr erhöht den Blutdruck dosisabhängig (besonders bei Salzsensitivität, Älteren und CKD) und ist mit Schlaganfall und kardiovaskulären Ereignissen assoziiert; sie fördert die Calciurie. Hypernatriämie ist fast immer Wassermangel (gestörter Durst im Alter, Diabetes insipidus); EFSA hat keinen UL abgeleitet.","quellen":"Überwiegend Speisesalz aus verarbeiteten Lebensmitteln wie Brot, Käse, Wurst und Fischkonserven (DGE) sowie Fertiggerichten. 1 g Kochsalz enthält rund 0,4 g Natrium.","labor":"Serum-Na⁺ spiegelt die Wasserbilanz, nicht den Natriumbestand oder die Zufuhr; die Zufuhr wird über 24-h-Urin-Natrium geschätzt (Vollständigkeit über Kreatinin prüfen). Pseudohyponatriämie bei schwerer Hyperlipidämie oder Paraproteinämie mit indirekter ISE, Translokationshyponatriämie bei Hyperglykämie; Differenzierung über Serum- und Urinosmolalität, Urin-Na⁺ und Volumenstatus.","interaktion":"Natrium und Kalium wirken gegensinnig auf den Blutdruck (Na/K-Verhältnis); hohe Salzzufuhr steigert die Calciurie und schwächt Antihypertensiva ab. Natriumrestriktion und Thiazide erhöhen Lithiumspiegel (proximale Rückresorption); Thiazide, SSRI und Carbamazepin begünstigen Hyponatriämie.","ref":{"wert":"1500 mg/Tag (Erwachsene, m und w)","art":"Schätzwert","quelle":"https://www.dge.de/wissenschaft/referenzwerte/natrium/","stand":"2016"},"ul":null,"links":{"dis":["hyponatriaemie","hypernatriaemie","arterielle_hypertonie","siadh","herzinsuffizienz","leberzirrhose","aszites","morbus_addison","avp_mangel","mukoviszidose","chronische_nierenkrankheit"],"path":["raas"]},"mcq":[{"q":"Ein älterer Mann ernährt sich seit Wochen fast nur von Bier, trinkt viel und hat Na⁺ 118 mmol/l bei sehr niedriger Urinosmolalität. Welcher Mechanismus erklärt die Hyponatriämie?","a":"Die geringe Solutzufuhr begrenzt die renale Freiwasserausscheidung","w":["Bier stimuliert die ADH-Sekretion und hemmt so die Wasserdiurese","Alkohol steigert die renale Natriumausscheidung durch ENaC-Hemmung","Ethanol verschiebt Natrium über die Na⁺/K⁺-ATPase nach intrazellulär"],"why":"Wasserausscheidung ist an die Osmolausscheidung gekoppelt; trotz maximal verdünntem Urin (ADH supprimiert) reicht die geringe Solutmenge nicht aus."},{"q":"Bei schwerer Hypertriglyzeridämie misst die indirekte ISE ein Natrium von 126 mmol/l, die gemessene Serumosmolalität ist normal. Was liegt vor?","a":"Pseudohyponatriämie durch Verdrängung der Wasserphase durch Lipide","w":["Hypotone Hyponatriämie durch SIADH bei begleitender Pankreatitis","Translokationshyponatriämie durch osmotisch aktive Triglyzeride","Hypervolämische Hyponatriämie durch lipidbedingte Ödembildung"],"why":"Indirekte ISE verdünnen die Probe und unterstellen einen normalen Wasseranteil; die direkte ISE (Blutgasanalyse) zeigt ein normales Na⁺."},{"q":"Warum enthalten orale Rehydratationslösungen Glukose und Natrium in definiertem Verhältnis?","a":"SGLT1 transportiert Na⁺ und Glukose gekoppelt, Wasser folgt – auch bei sekretorischer Diarrhö","w":["Glukose hemmt die cAMP-vermittelte Chloridsekretion über CFTR direkt","Natrium steigert die Insulinsekretion und damit die insulinabhängige enterale Glukoseaufnahme deutlich","Glukose aktiviert ENaC im Kolon und senkt dadurch die Stuhlfrequenz"],"why":"Der SGLT1-Kotransport bleibt bei toxinvermittelter Sekretion intakt; deshalb wirkt ORS z. B. bei Cholera."}]},{"id":"chlorid","name":"Chlorid","gruppe":"Mengenelemente","aktiveForm":"Cl⁻ (Hauptanion des Extrazellulärraums)","funktion":"Bestimmt mit Na⁺ Osmolalität und Extrazellulärvolumen, ist Bestandteil der Magensalzsäure (Parietalzelle: H⁺/K⁺-ATPase mit apikalen Cl⁻-Kanälen) und wichtig für den Säure-Basen-Haushalt (Cl⁻/HCO₃⁻-Austausch, Chloridverschiebung im Erythrozyten). Zudem Sekretion über CFTR (Atemwege, Pankreas, Schweißdrüse) und neuronale Hemmung über GABA-A- und Glycinrezeptoren.","aufnahme":"Nahezu vollständige Absorption, überwiegend gekoppelt an Na⁺ (parazellulär, Cl⁻/HCO₃⁻-Austauscher). Renale Rückresorption gemeinsam mit Na⁺ (NKCC2 im dicken aufsteigenden Henle-Schenkel, NCC im distalen Tubulus, Pendrin); die Macula densa erfasst die tubuläre NaCl-Konzentration über NKCC2 und steuert Reninfreisetzung und tubuloglomeruläres Feedback.","mangel":"Ernährungsbedingt praktisch nur historisch (chloridarme Säuglingsnahrung mit Gedeihstörung und hypochlorämischer Alkalose). Klinisch relevant ist der Verlust mit hypochlorämischer metabolischer Alkalose, Hypovolämie, Hypokaliämie, Muskelschwäche und Herzrhythmusstörungen.","risiko":"Erbrechen oder abgeleitete Magensonde, Schleifen- und Thiaziddiuretika, Mukoviszidose (Salzverlust über Schweiß), kongenitale Chloriddiarrhö, Bartter-/Gitelman-Syndrom, chronische Nierenkrankheit (DGE), Laxanzien- und Diuretikaabusus.","ueberdosis":"Die Zufuhr erfolgt fast ausschließlich als NaCl, die Risiken entsprechen der Kochsalzzufuhr. Hyperchlorämie entsteht v. a. iatrogen durch große Mengen 0,9 % NaCl (hyperchlorämische metabolische Azidose) oder durch Bicarbonatverlust (Diarrhö, renale tubuläre Azidose); EFSA hat keinen UL abgeleitet.","quellen":"Hauptquelle ist Speisesalz (NaCl besteht nach Masse zu etwa 60 % aus Chlorid) in verarbeiteten Lebensmitteln wie Brot, Käse und Wurst (DGE); daneben Kaliumchlorid in Salzersatz.","labor":"Serumchlorid dient der Säure-Basen-Analyse: Die Anionenlücke (Na⁺ − [Cl⁻ + HCO₃⁻]) trennt Additions- von Subtraktionsazidosen. Ein niedriges Urin-Chlorid kennzeichnet die chloridsensitive Alkalose (Erbrechen, nach Diuretika), ein hohes die chloridresistente (Mineralokortikoidexzess, aktive Diuretika); der Schweißchloridtest ist Goldstandard der Mukoviszidose-Diagnostik.","interaktion":"Untrennbar an Natrium gekoppelt (Zufuhr und renale Rückresorption); Schleifen- und Thiaziddiuretika steigern die Ausscheidung. Kalium- und Chloridmangel unterhalten gemeinsam die metabolische Alkalose, die ohne Chloridersatz nicht korrigiert wird.","ref":{"wert":"2300 mg/Tag (Erwachsene, m und w)","art":"Schätzwert","quelle":"https://www.dge.de/wissenschaft/referenzwerte/chlorid/","stand":"2016"},"ul":null,"links":{"dis":["metabolische_alkalose","metabolische_azidose","renale_tubulaere_azidose","mukoviszidose","bulimia_nervosa"],"path":["raas"]},"mcq":[{"q":"Eine Patientin mit Bulimia nervosa hat eine metabolische Alkalose, ein sehr niedriges Urin-Chlorid, aber ein nicht erniedrigtes Urin-Natrium. Was spricht am ehesten für Erbrechen als Ursache?","a":"Das niedrige Urin-Chlorid, da Natrium mit dem Bicarbonat ausgeschieden wird","w":["Das normale Urin-Natrium, das einen relevanten Volumenmangel sicher ausschließt","Die Alkalose, die ausschließlich bei Diuretikaabusus auftreten kann","Das niedrige Urin-Chlorid, das einen Mineralokortikoidexzess beweist"],"why":"Bei Erbrechen wird Bicarbonat mit Na⁺ ausgeschieden, Urin-Na⁺ ist daher unzuverlässig; ein niedriges Urin-Cl⁻ zeigt die chloridsensitive Alkalose an, bei aktiver Diuretikaeinnahme wäre es hoch."},{"q":"Ein Intensivpatient erhält mehrere Liter 0,9 % NaCl und entwickelt eine metabolische Azidose mit normaler Anionenlücke. Was ist der Mechanismus?","a":"Hyperchlorämie senkt die starke Ionendifferenz und damit das Bicarbonat","w":["Laktatazidose durch Gewebshypoperfusion bei Volumenüberladung","Ketonkörperbildung durch fehlende Glukose in der Infusion","Albuminverdünnung mit konsekutivem Anstieg der Anionenlücke"],"why":"0,9 % NaCl enthält gleich viel Na⁺ und Cl⁻ und damit relativ mehr Chlorid als Plasma; nach Stewart sinkt die SID, und HCO₃⁻ fällt."},{"q":"Welcher Befund ist bei Mukoviszidose diagnostisch wegweisend und warum?","a":"Erhöhtes Schweißchlorid durch fehlende CFTR-vermittelte Resorption im Ausführungsgang","w":["Erniedrigtes Schweißchlorid durch kompensatorisch gesteigerte CFTR-Sekretion im Drüsenknäuel","Erhöhtes Serumchlorid durch renale Chloridretention bei CFTR-Defekt","Erniedrigtes Urinchlorid durch gesteigerte Pendrin-Aktivität im Sammelrohr"],"why":"Im Ausführungsgang resorbiert CFTR Cl⁻ (Na⁺ folgt über ENaC); fehlt CFTR, bleibt der Schweiß salzreich – Salzverlust und hypochlorämische Alkalose bei Hitze sind möglich."}]},{"id":"eisen","name":"Eisen","gruppe":"Spurenelemente","aktiveForm":"Hämeisen (Hämoglobin, Myoglobin, Cytochrome), Eisen-Schwefel-Cluster und Nicht-Häm-Enzymeisen; Transport als Fe³⁺-Transferrin, Speicherung als Ferritin/Hämosiderin","funktion":"Sauerstofftransport und -speicherung (Hämoglobin, Myoglobin), Elektronentransport in der Atmungskette (Cytochrome, Fe-S-Cluster der Komplexe I–III) und Enzymkofaktor (Katalase, Peroxidasen, Cytochrom P450, Ribonukleotidreduktase, Tyrosin- und Tryptophanhydroxylase, Thyreoperoxidase). Damit relevant für DNA-Synthese, Neurotransmitter- und Schilddrüsenhormonbildung.","aufnahme":"Nicht-Hämeisen wird durch duodenales Cytochrom b (DcytB) und Ascorbat zu Fe²⁺ reduziert und über DMT1 aufgenommen, Hämeisen separat und durch die Hämoxygenase freigesetzt. Export über Ferroportin, Oxidation durch das kupferhaltige Hephaestin, Bindung an Transferrin; Hepcidin (↑ bei Eisenüberschuss und Entzündung/IL-6, ↓ bei Eisenmangel und gesteigerter Erythropoese via Erythroferron) internalisiert Ferroportin. Eine regulierte Ausscheidung existiert nicht – die Homöostase erfolgt allein über die Absorption.","mangel":"Stadienhaft: Speichereisenmangel (Ferritin ↓), eisendefizitäre Erythropoese (Transferrinsättigung ↓, löslicher Transferrinrezeptor ↑, Zinkprotoporphyrin ↑), dann hypochrome mikrozytäre Anämie. Symptome: Müdigkeit, Leistungsminderung, Blässe, Haarausfall, Koilonychie, Mundwinkelrhagaden, Pica/Pagophagie, Restless-Legs-Syndrom, bei Kindern kognitive Beeinträchtigung.","risiko":"Menstruation (v. a. Hypermenorrhö), Schwangerschaft, Wachstum, Blutspende, Ausdauersport, vegetarische/vegane Ernährung, chronische Blutverluste (GI-Tumoren, Ulzera, NSAR, Antikoagulation), Zöliakie, Autoimmungastritis, H. pylori, bariatrische OP, CKD und Herzinsuffizienz. PPI und H2-Blocker mindern die Nicht-Häm-Absorption.","ueberdosis":"Akut (v. a. Kinder durch Eisentabletten): GI-Nekrosen, metabolische Azidose, Schock, Leberversagen. Chronische Überladung bei hereditärer Hämochromatose (HFE C282Y, Hepcidinmangel), Transfusionen oder ineffektiver Erythropoese (Thalassämie) → Leberzirrhose, HCC, Kardiomyopathie, Diabetes, Arthropathie, Hypogonadismus; EFSA nennt statt eines UL einen Safe Level of Intake.","quellen":"Hämeisen (gut verfügbar, wenig beeinflussbar): Fleisch, Leber, Blutwurst, Fisch. Nicht-Hämeisen: Vollkorn, Hülsenfrüchte, Hirse, Haferflocken, grünes Gemüse, Samen; Phytat, Polyphenole (Kaffee, schwarzer Tee) und Calcium hemmen, Vitamin C, organische Säuren und Fleisch fördern die Aufnahme (DGE).","labor":"Ferritin ist der beste Einzelmarker der Speicher, aber Akute-Phase-Protein: bei Entzündung, Leberzellschaden, Malignom oder Adipositas falsch normal bis hoch. Dann Transferrinsättigung, löslichen Transferrinrezeptor (entzündungsunabhängig), sTfR-Ferritin-Index, Retikulozytenhämoglobin und CRP mitbestimmen; Serumeisen allein ist wegen Tagesschwankung und Entzündungsabhängigkeit ungeeignet.","interaktion":"Calcium, hohe Zinkdosen, Phytat, Polyphenole und PPI hemmen, Vitamin C fördert die Aufnahme. Eisen mindert die Resorption von Levothyroxin, Tetrazyklinen, Fluorchinolonen, Levodopa und Bisphosphonaten (zeitlicher Abstand); Kupfermangel verursacht über Hephaestin/Coeruloplasmin eine eisenrefraktäre Anämie.","ref":{"wert":"m 11 mg/Tag; w 16 mg/Tag (prämenopausal, 19 bis <51 J.), 16 bzw. 14 mg/Tag (prä- bzw. postmenopausal, 51 bis <65 J.), 14 mg/Tag (ab 65 J.); nicht menstruierende Frauen 11 mg/Tag","art":"Empfehlung","quelle":"https://www.dge.de/wissenschaft/referenzwerte/eisen/","stand":"2023"},"ul":{"wert":"40 mg/Tag (Safe Level of Intake; kein UL ableitbar)","art":"Safe Level","quelle":"https://www.efsa.europa.eu/sites/default/files/2024-05/ul-summary-report.pdf (EFSA: Overview on Tolerable Upper Intake Levels, Version 11 (August 2025); Grundlage: EFSA NDA Panel 2024)"},"links":{"dis":["eisenmangel","eisenmangelanaemie","eisenmangelanaemie_schwangerschaft","anaemie_chronische_erkrankung","haemochromatose","thalassaemie","restless_legs_syndrom","zoeliakie","autoimmungastritis","helicobacter_gastritis","obere_gi_blutung","chronische_nierenkrankheit","herzinsuffizienz"],"path":["eisen","haem-bilirubin","atmungskette"]},"mcq":[{"q":"Eine Patientin mit aktiver rheumatoider Arthritis hat eine mikrozytäre Anämie, Ferritin 120 µg/l, erhöhtes CRP, niedrige Transferrinsättigung und erhöhten löslichen Transferrinrezeptor. Wie ist das zu deuten?","a":"Kombination aus Entzündungsanämie und echtem Eisenmangel","w":["Reine Entzündungsanämie, da ein normales Ferritin Eisenmangel ausschließt","Eisenüberladung, da Ferritin und Transferrinsättigung diskordant sind","Thalassämie-Trait, da sTfR bei Eisenmangel stets normal bleibt"],"why":"Ferritin steigt als Akute-Phase-Protein; der entzündungsunabhängige sTfR zeigt den Eisenbedarf des Erythrons an (hoher sTfR-Ferritin-Index)."},{"q":"Warum steigt bei chronischer Entzündung die intestinale Eisenaufnahme nicht, obwohl die Erythropoese Eisen benötigt?","a":"IL-6 induziert Hepcidin, das Ferroportin internalisiert und den Eisenexport blockiert","w":["Interferon-γ steigert die biliäre Eisenausscheidung und leert so die hepatischen Eisenspeicher","Entzündung senkt die Transferrinsynthese, sodass kein Eisen gebunden wird","CRP bindet Nicht-Hämeisen im Darmlumen und macht es unlöslich"],"why":"Hepcidin blockiert Ferroportin in Enterozyten und Makrophagen; Eisen bleibt im RES gefangen (funktioneller Eisenmangel, Entzündungsanämie)."},{"q":"Bei einem Mann mit HFE-C282Y-Homozygotie ist die Transferrinsättigung stark erhöht. Welcher Mechanismus liegt der Eisenüberladung zugrunde?","a":"Inadäquat niedriges Hepcidin mit ungebremstem Ferroportin-Export","w":["Gesteigerte DMT1-Expression durch Funktionsverlust des Ferroportins","Fehlende renale Eisenausscheidung durch HFE-Defekt im Tubulus","Verminderte Ferritinsynthese mit Freisetzung von Speichereisen"],"why":"HFE ist Teil der hepatischen Eisensensorik (BMP/SMAD); fehlt es, wird zu wenig Hepcidin gebildet und Enterozyten wie Makrophagen exportieren ungebremst Eisen."}]},{"id":"zink","name":"Zink","gruppe":"Spurenelemente","aktiveForm":"Zn²⁺ als katalytischer oder struktureller Bestandteil von Metalloenzymen und Zinkfingerproteinen; intrazellulär an Metallothionein gebunden","funktion":"Kofaktor mehrerer hundert Enzyme aller Enzymklassen, z. B. Carboanhydrase, alkalische Phosphatase, Alkoholdehydrogenase, Cu/Zn-Superoxiddismutase, δ-Aminolävulinsäure-Dehydratase, Carboxypeptidasen und Matrixmetalloproteinasen; strukturell in Zinkfingern von Transkriptionsfaktoren und Hormonrezeptoren. Essenziell für Zellteilung, Immunfunktion (T-Zellen, Thymulin), Wundheilung, Geschmack, Spermatogenese und Insulinspeicherung.","aufnahme":"Aufnahme im Dünndarm über ZIP4 (SLC39A4), basolateraler Export über ZnT1, im Plasma überwiegend an Albumin gebunden. Es gibt keinen klassischen Speicher (DGE), sondern einen kleinen, rasch austauschbaren Pool; die Homöostase erfolgt über Anpassung der Absorption und die endogene Ausscheidung mit Pankreas- und Darmsekreten, Metallothionein in der Enterozyte reguliert den Transfer.","mangel":"Früh: Geschmacks- und Geruchsstörung, Appetitlosigkeit, Wundheilungsstörung, Infektanfälligkeit. Später periorifizielle und akrale Dermatitis, Alopezie, Diarrhö, Wachstums- und Pubertätsverzögerung, Hypogonadismus, Nachtblindheit (gestörter Vitamin-A-Stoffwechsel); Acrodermatitis enteropathica als angeborener ZIP4-Defekt, typischerweise nach dem Abstillen.","risiko":"Phytatreiche, tierproteinarme Kost, Malabsorption (Morbus Crohn, Zöliakie, Kurzdarm, bariatrische OP, exokrine Pankreasinsuffizienz), Alkoholabhängigkeit, Leberzirrhose, CKD/Dialyse, Diabetes (Zinkurie), Sichelzellkrankheit, Verbrennungen. Medikamente: Thiazide und ACE-Hemmer (Zinkurie), Penicillamin und andere Chelatbildner.","ueberdosis":"Akut Übelkeit, Erbrechen und Bauchschmerzen. Chronisch hohe Zufuhr induziert Metallothionein in Enterozyten, das Kupfer bindet und mit abgeschilferten Zellen ausscheidet – Kupfermangel mit Anämie, Neutropenie und Myelopathie ist der kritische Effekt des UL (auch durch zinkhaltige Prothesenhaftcremes beschrieben).","quellen":"Fleisch, Innereien, Austern und Meeresfrüchte, Käse, Eier, Vollkorn, Hülsenfrüchte, Nüsse und Samen. Die Bioverfügbarkeit hängt stark vom Phytat ab (DGE staffelt die Empfehlung nach Phytatzufuhr); Einweichen, Keimen, Sauerteig und tierisches Protein verbessern sie.","labor":"Serum-/Plasma-Zink ist wenig sensitiv und sinkt unabhängig vom Status bei Entzündung (Umverteilung in die Leber), Hypalbuminämie, nach Mahlzeiten und im Tagesverlauf; Hämolyse und Kontamination erhöhen falsch (zinkfreie Röhrchen, nüchtern morgens). Eine erniedrigte alkalische Phosphatase kann ein Hinweis sein; das Ansprechen auf Substitution bestätigt die Diagnose.","interaktion":"Hohe Zinkzufuhr verursacht Kupfermangel (Metallothionein) und konkurriert in hoher Dosis mit Eisen; Calcium und Phytat hemmen die Aufnahme. Zink bildet Komplexe mit Tetrazyklinen und Fluorchinolonen (zeitlicher Abstand); beim Morbus Wilson wird dieser Mechanismus genutzt, um die Kupferaufnahme zu blockieren.","ref":{"wert":"m 11 / 14 / 16 mg/Tag, w 7 / 8 / 10 mg/Tag bei niedriger / mittlerer / hoher Phytatzufuhr (Erwachsene)","art":"Empfehlung","quelle":"https://www.dge.de/wissenschaft/referenzwerte/zink/","stand":"2019"},"ul":{"wert":"25 mg/Tag","art":"UL","quelle":"https://www.efsa.europa.eu/sites/default/files/2024-05/ul-summary-report.pdf (EFSA: Overview on Tolerable Upper Intake Levels, Version 11 (August 2025); Grundlage: SCF 2002)"},"links":{"dis":["zinkmangel","acrodermatitis_enteropathica","kupfermangel_myelopathie","morbus_wilson","morbus_crohn","sekundaerer_immundefekt","leberzirrhose","alkoholabhaengigkeit","telogenes_effluvium","sichelzellkrankheit"],"path":["alkoholabbau","haem-bilirubin"]},"mcq":[{"q":"Eine Frau mit unklarer Anämie, Neutropenie und spastischer Gangstörung verwendet seit Jahren große Mengen zinkhaltiger Prothesenhaftcreme. Welcher Mechanismus erklärt das Bild?","a":"Zinkinduziertes Metallothionein bindet Kupfer in Enterozyten und verhindert dessen Aufnahme","w":["Zink hemmt die Methioninsynthase und verursacht so eine funikuläre Myelose","Zink verdrängt Eisen aus Transferrin und verursacht eine Eisenmangelanämie","Zink blockiert den intestinalen Thiamintransport und verursacht eine Wernicke-Enzephalopathie"],"why":"Metallothionein hat eine hohe Kupferaffinität; gebundenes Kupfer geht mit abgeschilferten Enterozyten verloren – die Kupfermangel-Myelopathie imitiert den B12-Mangel."},{"q":"Warum ist ein erniedrigtes Plasma-Zink während einer akuten Pneumonie nur eingeschränkt verwertbar?","a":"In der Akutphase verlagert IL-6 Zink über ZIP14 und Metallothionein in die Leber","w":["In der Akutphase steigt die renale Zinkausscheidung auf ein Vielfaches","Antibiotika binden Zink als Chelat im Plasma und verfälschen die Messung systematisch","Fieber denaturiert Zink-Albumin-Komplexe bereits im Probenröhrchen"],"why":"Die Hypozinkämie ist Teil der Akute-Phase-Reaktion und spiegelt nicht den Körperbestand; CRP und Albumin sind mitzubeurteilen."},{"q":"Ein Säugling entwickelt einige Wochen nach dem Abstillen periorifizielle Dermatitis, Alopezie und Durchfall ohne neurologische Auffälligkeiten; die alkalische Phosphatase ist niedrig. Welcher Defekt ist wahrscheinlich?","a":"Mutation des intestinalen Zinktransporters ZIP4 (SLC39A4)","w":["Mutation der kupfertransportierenden P-Typ-ATPase ATP7A im Darm","Mutation des Biotin-Recyclingenzyms Biotinidase","Mutation des Riboflavintransporters RFVT3"],"why":"Muttermilchzink ist gut verfügbar; nach dem Abstillen demaskiert sich die Acrodermatitis enteropathica, die niedrige AP (Zinkenzym) passt dazu."}]},{"id":"kupfer","name":"Kupfer","gruppe":"Spurenelemente","aktiveForm":"Cu⁺/Cu²⁺ als Redoxzentrum von Cuproenzymen; im Plasma überwiegend an Coeruloplasmin gebunden","funktion":"Redoxaktiver Kofaktor von Cytochrom-c-Oxidase (Komplex IV), Cu/Zn-Superoxiddismutase, den Ferroxidasen Coeruloplasmin und Hephaestin (Fe²⁺ → Fe³⁺ für die Transferrinbeladung), Lysyloxidase (Quervernetzung von Kollagen und Elastin), Dopamin-β-Hydroxylase und Tyrosinase (Melanin).","aufnahme":"Reduktion zu Cu⁺ und Aufnahme über CTR1 im Dünndarm, basolateraler Export über ATP7A, Transport im Pfortaderblut an Albumin und Histidin. Hepatozyten bauen Kupfer über ATP7B in Coeruloplasmin ein oder scheiden es biliär aus; die biliäre Ausscheidung ist der Hauptregulator der Homöostase.","mangel":"Hämatologisch: Anämie (mikro-, normo- oder makrozytär), Neutropenie, Ringsideroblasten – kann ein MDS imitieren. Neurologisch: Myeloneuropathie mit Hinterstrangbefall und spastischer Ataxie (B12-Mangel-ähnlich), Optikusneuropathie; zudem Osteoporose und Hypopigmentierung; die Menkes-Krankheit beruht auf einem X-chromosomalen ATP7A-Defekt.","risiko":"Bariatrische OP (v. a. Magenbypass), Gastrektomie, Malabsorption, hohe Zinkzufuhr (Supplemente, Haftcremes), langfristige parenterale Ernährung ohne Kupfer, Frühgeborene, überdosierte Chelattherapie beim Morbus Wilson.","ueberdosis":"Akut GI-Beschwerden, Hämolyse sowie Leber- und Nierenschäden (z. B. Kupfersulfat). Chronische Toxizität v. a. bei gestörter biliärer Ausscheidung: Morbus Wilson (ATP7B) mit Leberzirrhose, neuropsychiatrischen Symptomen und Kayser-Fleischer-Ring; kritischer Effekt des SCF-UL ist die Leberschädigung.","quellen":"Innereien (Leber), Schalentiere, Nüsse, Samen, Kakao, Vollkorn, Hülsenfrüchte, grünes Gemüse, Kaffee und Tee (DGE); Trinkwasser aus Kupferleitungen bei weichem, saurem Wasser.","labor":"Serumkupfer und Coeruloplasmin sinken bei Mangel, steigen aber als Akute-Phase-Reaktanten sowie unter Östrogenen und in der Schwangerschaft und können einen Mangel maskieren; niedrig sind sie auch bei Morbus Wilson und Proteinverlust. Bei Wilson-Verdacht: Coeruloplasmin ↓, 24-h-Urinkupfer ↑, nicht coeruloplasmingebundenes Kupfer ↑, Leberkupfer.","interaktion":"Zink (Metallothionein) und hohe Eisenzufuhr hemmen die Aufnahme; Molybdän bildet als Thiomolybdat Kupferkomplexe. Kupfermangel verursacht über Hephaestin-/Coeruloplasminmangel eine eisenrefraktäre Anämie; Penicillamin und Trientin chelatieren Kupfer.","ref":{"wert":"1,0–1,5 mg/Tag (Jugendliche und Erwachsene, m und w)","art":"Schätzwert","quelle":"https://www.dge.de/wissenschaft/referenzwerte/kupfer-mangan-chrom-molybdaen/","stand":"2000"},"ul":{"wert":"5 mg/Tag","art":"UL","quelle":"https://www.efsa.europa.eu/sites/default/files/2024-05/ul-summary-report.pdf (EFSA: Overview on Tolerable Upper Intake Levels, Version 11 (August 2025); Grundlage: SCF 2003); zusätzlich EFSA Scientific Committee 2023: ADI 0,07 mg/kg Körpergewicht"},"links":{"dis":["kupfermangel_myelopathie","morbus_wilson","akutes_leberversagen","mds","sideroblastische_anaemie","funikulaere_myelose","adipositas"],"path":["eisen","atmungskette"]},"mcq":[{"q":"Fünf Jahre nach Roux-en-Y-Magenbypass hat ein Patient Anämie, Neutropenie und eine sensible Ataxie; B12 und Folat sind normal. Welcher Mangel ist am wahrscheinlichsten?","a":"Kupfermangel mit Myelopathie und Zytopenie","w":["Vitamin-E-Mangel mit spinozerebellärer Degeneration","Thiaminmangel mit Wernicke-Enzephalopathie","Eisenmangel mit Restless-Legs-Syndrom und Anämie"],"why":"Kupfermangel imitiert die B12-Myelopathie und ein MDS (Neutropenie, Ringsideroblasten); Duodenum und proximales Jejunum werden beim Bypass umgangen."},{"q":"Bei einer jungen Patientin mit hepatischen und psychiatrischen Symptomen sind Coeruloplasmin niedrig und 24-h-Urinkupfer erhöht. Welcher Defekt passt?","a":"ATP7B-Defekt mit gestörter biliärer Kupferausscheidung","w":["ATP7A-Defekt mit gestörtem intestinalem Kupferexport","CTR1-Defekt mit gestörter zellulärer Kupferaufnahme","Hephaestin-Defekt mit gestörter enteraler Eisenoxidation"],"why":"Beim Morbus Wilson wird Kupfer weder in Apo-Coeruloplasmin eingebaut (rascher Abbau) noch in die Galle ausgeschieden; freies Kupfer akkumuliert und erscheint im Urin."},{"q":"Warum kann bei schwerer Entzündung trotz Kupfermangel ein normales Coeruloplasmin gemessen werden?","a":"Coeruloplasmin ist ein Akute-Phase-Protein und wird bei Entzündung vermehrt gebildet","w":["Coeruloplasmin wird bei Entzündung kupferunabhängig an Albumin gebunden und dadurch stabilisiert","Entzündung blockiert den renalen Abbau von Coeruloplasmin vollständig","IL-6 steigert die intestinale Kupferaufnahme über CTR1 massiv"],"why":"Die Akute-Phase-Induktion (ebenso Östrogene und Schwangerschaft) kann einen Mangel maskieren; Bewertung daher stets mit CRP und Klinik."}]},{"id":"selen","name":"Selen","gruppe":"Spurenelemente","aktiveForm":"Selenocystein (21. proteinogene Aminosäure) in Selenoproteinen; Nahrungsformen Selenomethionin (unspezifisch in Proteine eingebaut) sowie Selenit/Selenat","funktion":"Selenocystein bildet das katalytische Zentrum der rund 25 humanen Selenoproteine: Glutathionperoxidasen (Abbau von H₂O₂ und Lipidhydroperoxiden), Thioredoxinreduktasen, Iodthyronin-Deiodasen (Aktivierung von T4 zu T3 bzw. Inaktivierung) und Selenoprotein P (Selentransport). Wichtig für antioxidative Abwehr, Schilddrüsenhormonstoffwechsel, Immunfunktion und Spermienbildung (GPx4).","aufnahme":"Selenomethionin wird über Methionintransporter, Selenit und Selenat werden effizient aufgenommen; Umbau zu Selenid und Einbau als Selenocystein über eine eigene tRNA (UGA-Codon, SECIS-Element). Selenoprotein P verteilt Selen von der Leber an die Gewebe; Ausscheidung renal (Selenozucker, Trimethylselenonium) und bei hoher Zufuhr pulmonal als Dimethylselenid (Knoblauchgeruch).","mangel":"Keshan-Krankheit (endemische Kardiomyopathie in selenarmen Regionen Chinas, Kofaktor Coxsackievirus) und Kashin-Beck-Krankheit (Osteoarthropathie). Unter parenteraler Ernährung ohne Selen Myopathie, Kardiomyopathie, Makrozytose und weiße Nagelbetten; subklinisch verminderte GPx-Aktivität.","risiko":"Niedriger Bodenselengehalt mit entsprechend selenarmer Pflanzenkost, vegane Ernährung (DGE: potenziell kritisch), langfristige parenterale Ernährung, Dialyse, Malabsorption (Morbus Crohn, Kurzdarm), Phenylketonurie-Diät, Alkoholabhängigkeit, kritische Erkrankung.","ueberdosis":"Selenose: Haar- und Nagelverlust, Hautausschlag, Knoblauchatem, Metallgeschmack, GI-Beschwerden, Neuropathie, Müdigkeit. Kritischer Effekt des EFSA-UL (2023) ist Alopezie als frühes Zeichen (LOAEL aus der SELECT-Studie); Paranüsse enthalten sehr viel und stark schwankend Selen (DGE: höchstens zwei Stück pro Tag).","quellen":"Fisch, Meeresfrüchte, Fleisch, Innereien, Eier; Paranüsse. Pflanzliche Gehalte schwanken stark mit dem Bodenselen (DGE), pflanzliche Lieferanten sind Kohl- und Zwiebelgemüse, Pilze, Spargel und Hülsenfrüchte.","labor":"Plasma- bzw. Serumselen spiegelt die mittelfristige Zufuhr, sinkt aber in der Akutphase. Selenoprotein P ist der beste funktionelle Marker bis zur Sättigung, die Plasma-GPx3-Aktivität sättigt früher; Vollblut-, Erythrozyten- und Nagelselen zeigen den Langzeitstatus, Haarwerte sind durch selenhaltige Shampoos verfälschbar.","interaktion":"Selen und Jod: Deiodasen sind selenabhängig, GPx schützt die Schilddrüse vor H₂O₂ – bei kombiniertem Mangel zuerst Jod ausgleichen. Vitamin E und Selen wirken synergistisch gegen Lipidperoxidation; Selen bindet Quecksilber und mindert dessen Toxizität.","ref":{"wert":"m 70 / w 60 µg/Tag (Erwachsene)","art":"Schätzwert","quelle":"https://www.dge.de/wissenschaft/referenzwerte/selen/","stand":"2015"},"ul":{"wert":"255 µg/Tag","art":"UL","quelle":"https://www.efsa.europa.eu/sites/default/files/2024-05/ul-summary-report.pdf (EFSA: Overview on Tolerable Upper Intake Levels, Version 11 (August 2025); Grundlage: EFSA NDA Panel 2023)"},"links":{"dis":["hashimoto","hypothyreose","morbus_basedow","jodmangel","dilatative_kardiomyopathie","kurzdarmsyndrom"],"path":[]},"mcq":[{"q":"Warum kann eine isolierte Selengabe bei schwerem, unkorrigiertem Jodmangel die Hypothyreose verschlechtern?","a":"Gesteigerte Deiodaseaktivität beschleunigt den Abbau des knappen T4","w":["Selen hemmt die Thyreoperoxidase und blockiert die Jodierung","Selen konkurriert mit Iodid um den Natrium-Iodid-Symporter","Selen fördert die Bildung von Antikörpern gegen die TPO"],"why":"Mehr Deiodase-Aktivität verbraucht T4 schneller, das ohne Jod nicht nachgebildet wird; daher zuerst Jod, dann Selen ausgleichen."},{"q":"Welcher Biomarker spiegelt die Selenversorgung der Gewebe am besten wider, solange keine Sättigung erreicht ist?","a":"Selenoprotein-P-Konzentration im Plasma","w":["Selenkonzentration im Kopfhaar","Glutathionreduktase-Aktivität im Erythrozyten","Urinausscheidung von Dimethylselenid"],"why":"SELENOP ist das Transportprotein und reagiert über einen breiteren Zufuhrbereich als GPx3; die Glutathionreduktase ist FAD-, nicht selenabhängig."},{"q":"Unter langjähriger parenteraler Ernährung ohne Spurenelemente entwickelt ein Patient Muskelschwäche, weiße Nagelbetten und eine dilatative Kardiomyopathie. Welcher Mangel passt am besten?","a":"Selenmangel mit verminderter Glutathionperoxidase-Aktivität","w":["Chrommangel mit gestörter Insulinwirkung im Myokard","Molybdänmangel mit gestörtem Sulfitabbau im Muskel","Manganmangel mit verminderter MnSOD-Aktivität im Herzen"],"why":"Selenmangel unter PN imitiert die Keshan-Kardiomyopathie; Myopathie und Leukonychie sind typische Begleitzeichen."}]},{"id":"jod","name":"Jod (Iod)","gruppe":"Spurenelemente","aktiveForm":"Iodid (I⁻) als Substrat; wirksam als Bestandteil der Schilddrüsenhormone Thyroxin (T4) und Triiodthyronin (T3)","funktion":"Die Thyreoperoxidase bindet Iodid H₂O₂-abhängig an Tyrosylreste des Thyreoglobulins (MIT, DIT) und koppelt sie zu T4 und T3. T3 reguliert über nukleäre Rezeptoren Grundumsatz, Thermogenese, Wachstum sowie die Gehirnentwicklung (Myelinisierung) in Fetal- und Säuglingszeit.","aufnahme":"Iodid wird nahezu vollständig im Dünndarm aufgenommen und aktiv über den TSH-stimulierten Natrium-Iodid-Symporter (NIS) in die Schilddrüse transportiert, apikal über Pendrin ins Kolloid. Ausscheidung überwiegend renal, sodass das Urin-Iod die aktuelle Zufuhr abbildet; NIS findet sich auch in Brustdrüse (Iod in Muttermilch), Plazenta, Magen und Speicheldrüsen.","mangel":"Struma durch TSH-vermittelte Hyperplasie, später Knoten und Autonomie, Hypothyreose. In Schwangerschaft und früher Kindheit körperliche und neuronale Entwicklungsstörungen bis Kretinismus; schon ein leichter Mangel in der Schwangerschaft wird mit geringerer kognitiver Leistungsfähigkeit der Kinder in Verbindung gebracht (DGE).","risiko":"Schwangere und Stillende (DGE: zusätzliches Supplement empfohlen), Verzicht auf Jodsalz, vegane Ernährung ohne Jodsalz oder Supplement, geringer Fisch- und Milchkonsum. Strumigene wie Thiocyanat (Maniok, Rauchen), Perchlorat und Nitrat sowie Selen- und Eisenmangel verstärken die Folgen.","ueberdosis":"Hohe Zufuhr kann bei Autonomie oder latentem Morbus Basedow eine Hyperthyreose auslösen (Jod-Basedow) und bei Autoimmunthyreoiditis eine Hypothyreose fördern; akut hohe Mengen hemmen die Hormonsynthese (Wolff-Chaikoff-Effekt), dem die gesunde Schilddrüse nach Tagen entkommt. Risikoquellen: Algenprodukte, jodhaltige Kontrastmittel, Amiodaron, Povidon-Iod.","quellen":"Seefisch und Meeresfrüchte, Milch und Eier (abhängig von der Tierfütterung), jodiertes Speisesalz auch in Brot, Wurst, Käse und Außer-Haus-Verpflegung (DGE). Getrocknete Algen enthalten teils extrem hohe und stark schwankende Mengen.","labor":"Die Iodausscheidung im Spontanurin (ggf. auf Kreatinin bezogen) ist ein Populationsmarker: Der Median beschreibt die Versorgung einer Gruppe, der Einzelwert schwankt stark mit der letzten Mahlzeit. Individuell werden TSH, fT4, Thyreoglobulin (steigt bei Mangel) und das Schilddrüsenvolumen im Ultraschall beurteilt.","interaktion":"Selen (Deiodasen, GPx) und Eisen (die TPO ist ein Hämenzym) sind für die Jodverwertung nötig. Thiocyanat und Perchlorat hemmen den NIS kompetitiv, Thionamide die TPO; Amiodaron und Kontrastmittel liefern große Jodmengen, Lithium hemmt die Hormonfreisetzung.","ref":{"wert":"150 µg/Tag (Erwachsene, m und w)","art":"Empfehlung","quelle":"https://www.dge.de/wissenschaft/referenzwerte/jod/","stand":"2025"},"ul":{"wert":"600 µg/Tag","art":"UL","quelle":"https://www.efsa.europa.eu/sites/default/files/2024-05/ul-summary-report.pdf (EFSA: Overview on Tolerable Upper Intake Levels, Version 11 (August 2025); Grundlage: SCF 2003)"},"links":{"dis":["jodmangel","struma","schilddruesenknoten","hypothyreose","kongenitale_hypothyreose","hyperthyreose","schilddruesenautonomie","hashimoto"],"path":[]},"mcq":[{"q":"Eine 70-Jährige mit langjähriger Knotenstruma aus einer früheren Jodmangelregion entwickelt Wochen nach einer CT mit jodhaltigem Kontrastmittel Tachykardie und Gewichtsverlust. Was ist der Mechanismus?","a":"Jod-Basedow: Autonome Areale bilden ungebremst Hormon aus dem Jodangebot","w":["Wolff-Chaikoff-Effekt: Jod steigert die TPO-Aktivität über Wochen","Das Kontrastmittel stimuliert den TSH-Rezeptor wie TRAK","Jodexzess hemmt die Deiodasen und verstärkt so die T4-Wirkung"],"why":"Autonomes Gewebe unterliegt nicht der TSH-Regulation und nutzt das Jodangebot; der Wolff-Chaikoff-Effekt hemmt dagegen die Synthese kurzfristig."},{"q":"Warum eignet sich die Iodkonzentration im Spontanurin nicht zur Diagnose eines individuellen Jodmangels?","a":"Sie schwankt stark mit Zufuhr und Hydratation und taugt nur als Gruppenmedian","w":["Iod wird überwiegend biliär ausgeschieden, der Urin enthält daher nur geringe Spuren","Sie korreliert nur mit dem T3-Spiegel, nicht aber mit der Jodzufuhr","Sie steigt bei Jodmangel paradox an, weil Speicher mobilisiert werden"],"why":"Iod wird überwiegend renal ausgeschieden, die Konzentration spiegelt Stunden bis Tage; für Individuen wären wiederholte Messungen nötig."},{"q":"Warum empfiehlt die DGE Schwangeren zusätzlich zu Jodsalz ein Jodsupplement?","a":"Die fetale Hirnentwicklung braucht mütterliches T4, und der Jodbedarf steigt","w":["Jod senkt in der Frühschwangerschaft ähnlich wie Folsäure das Risiko für Neuralrohrdefekte","Jod senkt über die TPO-Aktivität das Risiko eines Gestationsdiabetes","Jod aus Speisesalz wird in der Schwangerschaft nicht mehr resorbiert"],"why":"Bis zur Reifung der fetalen Schilddrüse ist der Fetus auf mütterliches T4 angewiesen; steigende GFR und plazentarer Transfer erhöhen den Bedarf."}]},{"id":"fluorid","name":"Fluorid","gruppe":"Spurenelemente","aktiveForm":"Fluorid-Ion (F⁻); im Zahnschmelz als Fluorapatit bzw. fluoridiertes Hydroxylapatit","funktion":"Ein klassisches Mangelsyndrom fehlt, Fluorid wirkt aber kariespräventiv: überwiegend lokal-topisch durch Förderung der Remineralisation, Hemmung der Demineralisation und Bildung säureresistenterer Apatite sowie durch Hemmung bakterieller Enzyme (Enolase). Im Knochen stimuliert Fluorid Osteoblasten, bei hoher Zufuhr verschlechtert sich jedoch die Knochenqualität.","aufnahme":"Rasche, überwiegend passive Absorption als undissoziierte Flusssäure (HF) in Magen und Dünndarm; Calcium, Magnesium und Aluminium bilden schwerlösliche Komplexe. Etwa die Hälfte wird beim Erwachsenen in Knochen und Zähne eingelagert (bei Kindern mehr), der Rest renal ausgeschieden – in saurem Urin wird mehr rückresorbiert.","mangel":"Kein spezifisches Mangelsyndrom; eine geringe Fluoridzufuhr erhöht das Kariesrisiko, besonders ohne topische Anwendung fluoridhaltiger Zahnpasta.","risiko":"Niedriger Fluoridgehalt des Trinkwassers (in Deutschland meist der Fall, DGE), Verzicht auf fluoridiertes Salz und Zahnpasta, hohe Zuckerzufuhr, Xerostomie (Speichelmangel).","ueberdosis":"Zahnfluorose (Schmelzflecken) bei längerfristig hoher Gesamtzufuhr während der Zahnbildung, laut DGE besonders bei Kindern von 2 bis 8 Jahren oberhalb von etwa 0,1 mg/kg/Tag; Skelettfluorose (Osteosklerose, Bandverkalkungen, Frakturen) bei chronisch sehr hoher Zufuhr. EFSA (2025) leitet ihren Safe Level aus möglichen Effekten auf das sich entwickelnde Nervensystem des Fetus ab, der auch Knochen und Schilddrüse schützen soll.","quellen":"Fluoridiertes Speisesalz, Trink- und Mineralwasser (Gehalt sehr variabel), schwarzer Tee, Fisch und Meeresfrüchte (DGE); topisch fluoridhaltige Zahnpflegeprodukte, deren Verschlucken bei Kindern zur Gesamtzufuhr beiträgt.","labor":"Kein etablierter Statusmarker in der klinischen Routine; Fluorid in Urin und Plasma spiegelt die kurzfristige Zufuhr bzw. Exposition. Entscheidend für die Beratung ist die Erfassung aller Quellen (Wasser, Salz, Tabletten, Zahnpasta).","interaktion":"Calcium, Magnesium und Aluminium (Milch, Antazida) senken die Fluoridabsorption. Fluoridquellen addieren sich: Supplement, fluoridiertes Salz und verschluckte Zahnpasta zusammen erhöhen bei Kindern das Fluoroserisiko.","ref":{"wert":"m 3,5 / w 3,0 mg/Tag Gesamtzufuhr (Erwachsene)","art":"Richtwert","quelle":"https://www.dge.de/wissenschaft/referenzwerte/fluorid/","stand":"2022"},"ul":{"wert":"3,3 mg/Tag (Safe Level of Intake für Erwachsene inkl. Schwangere; kein UL)","art":"Safe Level","quelle":"https://www.efsa.europa.eu/sites/default/files/2024-05/ul-summary-report.pdf (EFSA: Overview on Tolerable Upper Intake Levels, Version 11 (August 2025); Grundlage: EFSA Scientific Committee 2025); EFSA-Meldung 22.07.2025: https://www.efsa.europa.eu/et/news/fluoride-safety-updated-intake-levels-all-ages"},"links":{"dis":[],"path":[]},"mcq":[{"q":"Welcher Mechanismus erklärt den kariespräventiven Effekt von Fluorid nach heutigem Verständnis am besten?","a":"Überwiegend topische Förderung der Remineralisation und Bildung säureresistenterer Apatite","w":["Überwiegend systemischer Einbau in Dentin und Schmelz vor dem Zahndurchbruch über den Blutweg","Bakterizide Abtötung von Streptococcus mutans durch hohe Plasmaspiegel","Steigerung der Speichelamylase mit schnellerem Abbau von Zuckern"],"why":"Entscheidend ist die lokale Wirkung an der Schmelzoberfläche (Remineralisation, Hemmung der Demineralisation, Enolasehemmung); der präeruptive systemische Einbau spielt eine geringere Rolle."},{"q":"Ein 5-jähriges Kind erhält Fluoridtabletten, schluckt fluoridierte Zahnpasta, und die Familie nutzt fluoridiertes Salz. Welches Risiko steht im Vordergrund?","a":"Zahnfluorose der bleibenden Zähne durch die kumulative Gesamtzufuhr","w":["Skelettfluorose mit Bandverkalkungen innerhalb weniger Monate","Fluoridinduzierte Hypothyreose durch Hemmung der Deiodasen","Akute Fluoridvergiftung mit Hypokalzämie nach jeder Mahlzeit"],"why":"Während der Schmelzbildung führt eine dauerhaft hohe Gesamtzufuhr zu Schmelzflecken; Fluoridquellen sollen nicht kumuliert werden."},{"q":"Warum beeinflusst der Urin-pH die renale Fluoridausscheidung?","a":"In saurem Urin liegt mehr undissoziierte HF vor, die tubulär zurückdiffundiert","w":["Alkalischer Urin fällt Calciumfluorid aus, das nicht filtriert wird","Saurer Urin aktiviert einen tubulären Fluorid-Chlorid-Austauscher zur aktiven Sekretion","Fluorid wird nur bei alkalischem Urin glomerulär filtriert"],"why":"HF ist membrangängig: Ansäuerung erhöht Rückresorption und Retention, Alkalisierung beschleunigt die Elimination."}]},{"id":"mangan","name":"Mangan","gruppe":"Spurenelemente","aktiveForm":"Mn²⁺/Mn³⁺ als Metallkofaktor, u. a. in der mitochondrialen Mangan-Superoxiddismutase (MnSOD/SOD2), der Arginase und der Pyruvatcarboxylase","funktion":"Bestandteil bzw. Aktivator von Metalloenzymen: MnSOD (mitochondrialer Radikalschutz), Arginase (Harnstoffzyklus), Pyruvatcarboxylase und PEPCK (Glukoneogenese), Glykosyltransferasen (Proteoglykansynthese in Knorpel und Knochen) und Glutaminsynthetase im Gehirn.","aufnahme":"Geringe Absorption von nur wenigen Prozent, u. a. über DMT1 und ZIP8/ZIP14 und in Konkurrenz zu Eisen – Eisenmangel steigert die Manganaufnahme. Transport an Transferrin und Albumin; die Homöostase erfolgt v. a. über die biliäre Ausscheidung (abhängig von ZIP14 und SLC30A10), daher Akkumulation bei Cholestase und Leberzirrhose.","mangel":"Beim Menschen nicht eindeutig beschrieben; in experimentellen Depletionsstudien traten Dermatitis und veränderte Lipid- und Knochenparameter auf. Seltene SLC39A8-Mutationen verursachen einen Manganmangel mit Glykosylierungsstörung (CDG).","risiko":"Bei üblicher Mischkost praktisch kein Mangelrisiko; relevant sind genetische Transporterdefekte (SLC39A8).","ueberdosis":"Manganismus durch Inhalation (Schweißen, Bergbau), langfristige parenterale Ernährung, Leberzirrhose (gestörte biliäre Ausscheidung) oder Ephedronkonsum (Kaliumpermanganat): Parkinson-ähnliches Syndrom mit Dystonie, Hahnengang und psychiatrischen Symptomen bei schlechtem Levodopa-Ansprechen, im MRT T1-hyperintenser Globus pallidus. EFSA nennt statt eines UL einen Safe Level of Intake.","quellen":"Vollkorngetreide, Haferflocken, Nüsse, Hülsenfrüchte, grünes Blattgemüse und Tee (DGE), Gewürze; tierische Lebensmittel enthalten wenig. Phytat, Calcium und Eisen mindern die Aufnahme.","labor":"Es gibt keinen verlässlichen Statusmarker; Vollblut-Mangan ist aussagekräftiger als Serum, spiegelt aber v. a. hohe Expositionen. Bei Verdacht auf Akkumulation Vollblut-Mangan und kraniale MRT (T1-Signal im Pallidum).","interaktion":"Eisen und Mangan teilen DMT1 und Transferrin: Eisenmangel erhöht Aufnahme und Neurotoxizität, Eisengabe senkt sie; hohe Calcium- und Phytatzufuhr mindern die Absorption. Bei Cholestase und Leberzirrhose ist Mangan in der parenteralen Ernährung kritisch zu prüfen.","ref":{"wert":"2,0–5,0 mg/Tag (Jugendliche und Erwachsene, m und w)","art":"Schätzwert","quelle":"https://www.dge.de/wissenschaft/referenzwerte/kupfer-mangan-chrom-molybdaen/","stand":"2000"},"ul":{"wert":"8 mg/Tag (Safe Level of Intake; kein UL ableitbar)","art":"Safe Level","quelle":"https://www.efsa.europa.eu/sites/default/files/2024-05/ul-summary-report.pdf (EFSA: Overview on Tolerable Upper Intake Levels, Version 11 (August 2025); Grundlage: EFSA NDA Panel 2023)"},"links":{"dis":["leberzirrhose","hepatische_enzephalopathie","parkinson","kurzdarmsyndrom","eisenmangel"],"path":["glukoneogenese","harnstoffzyklus"]},"mcq":[{"q":"Bei einem Patienten mit Leberzirrhose zeigt die MRT bilateral T1-hyperintense Globi pallidi. Welche Ursache ist am wahrscheinlichsten?","a":"Manganablagerung durch gestörte biliäre Ausscheidung","w":["Kupferablagerung durch gesteigerte Coeruloplasminsynthese","Eisenablagerung durch Hepcidinüberschuss im Gehirn","Ammoniakablagerung durch Glutaminsynthetasemangel"],"why":"Mangan ist paramagnetisch und wird biliär eliminiert; bei Zirrhose akkumuliert es in den Basalganglien und kann einen Parkinsonismus mitverursachen."},{"q":"Warum steigt bei Eisenmangel das Risiko einer Manganakkumulation?","a":"Eisenmangel induziert DMT1, über das auch Mn²⁺ verstärkt aufgenommen wird","w":["Eisenmangel senkt über Hepcidin die biliäre Manganausscheidung","Mangan ersetzt Eisen im Hämoglobin und wird dort retiniert","Eisenmangel aktiviert die MnSOD und bindet Mangan in Mitochondrien"],"why":"Über die IRP/IRE-Regulation steigt DMT1 bei Eisenmangel; Personen mit niedrigem Ferritin zeigen höhere Blut-Manganspiegel."},{"q":"Ein langjähriger Schweißer entwickelt Parkinsonismus mit früher Gangstörung und schlechtem Levodopa-Ansprechen. Welcher Befund spricht für Manganismus statt idiopathisches Parkinson?","a":"Normaler Dopamintransporter-SPECT bei T1-hyperintensem Pallidum","w":["Deutlich reduzierte Putamenaufnahme im Dopamintransporter-SPECT","Asymmetrischer Ruhetremor mit gutem Levodopa-Ansprechen","Frühe Hyposmie und REM-Schlaf-Verhaltensstörung"],"why":"Mangan schädigt v. a. den Globus pallidus, die nigrostriatalen Terminalen bleiben weitgehend intakt – daher normaler DaT-Scan und schlechtes Levodopa-Ansprechen."}]},{"id":"molybdaen","name":"Molybdän","gruppe":"Spurenelemente","aktiveForm":"Molybdän-Cofaktor (Moco): Molybdän gebunden an Molybdopterin","funktion":"Moco ist Kofaktor von vier humanen Enzymen: Sulfitoxidase (Sulfit → Sulfat, Endschritt des Abbaus schwefelhaltiger Aminosäuren), Xanthinoxidoreduktase (Hypoxanthin → Xanthin → Harnsäure), Aldehydoxidase (Fremdstoffstoffwechsel) und mitochondriale Amidoxim-reduzierende Komponente (mARC).","aufnahme":"Molybdat wird effizient im Dünndarm aufgenommen; die Homöostase erfolgt über die renale Ausscheidung, die mit der Zufuhr steigt. Gewebebestand v. a. in Leber und Niere als Moco-haltige Enzyme.","mangel":"Ernährungsbedingt nur als Einzelfall unter langfristiger parenteraler Ernährung beschrieben (Tachykardie, Kopfschmerz, Nachtblindheit bis Koma; Hypermethioninämie, Harnsäure ↓). Genetischer Moco-Mangel oder isolierter Sulfitoxidasemangel: therapieresistente Neugeborenenkrämpfe, Linsenluxation, schwere Enzephalopathie.","risiko":"Praktisch nur langfristige parenterale Ernährung ohne Molybdän und angeborene Moco-Synthesedefekte (MOCS1, MOCS2, GPHN).","ueberdosis":"Geringe Toxizität beim Menschen; sehr hohe Zufuhr wurde in Beobachtungsdaten mit Hyperurikämie und gichtähnlichen Beschwerden in Verbindung gebracht. Grundlage des SCF-UL sind Effekte auf Fertilität und Entwicklung im Tierversuch; bei Wiederkäuern verursacht Molybdän über Thiomolybdat einen Kupfermangel.","quellen":"Hülsenfrüchte (Erbsen, Linsen, Bohnen) und Getreide (DGE), Nüsse, Innereien; der Gehalt pflanzlicher Lebensmittel hängt vom Boden ab.","labor":"Kein etablierter Statusmarker für die Routine; Urin-Molybdän spiegelt die Zufuhr. Bei Verdacht auf Moco- oder Sulfitoxidasemangel: Sulfit-Teststreifen im frischen Urin, S-Sulfocystein ↑, Harnsäure ↓ sowie Xanthin und Hypoxanthin ↑ (nur bei Moco-Mangel).","interaktion":"Kupfer und Molybdän sind Antagonisten: Thiomolybdat bindet Kupfer (pharmakologisch als Tetrathiomolybdat beim Morbus Wilson untersucht). Allopurinol hemmt die Moco-abhängige Xanthinoxidase.","ref":{"wert":"50–100 µg/Tag (Jugendliche und Erwachsene, m und w)","art":"Schätzwert","quelle":"https://www.dge.de/wissenschaft/referenzwerte/kupfer-mangan-chrom-molybdaen/","stand":"2000"},"ul":{"wert":"0,6 mg/Tag (600 µg)","art":"UL","quelle":"https://www.efsa.europa.eu/sites/default/files/2024-05/ul-summary-report.pdf (EFSA: Overview on Tolerable Upper Intake Levels, Version 11 (August 2025); Grundlage: SCF 2000)"},"links":{"dis":["gicht","morbus_wilson","epilepsie"],"path":["purinabbau"]},"mcq":[{"q":"Ein Neugeborenes mit therapieresistenten Krampfanfällen hat eine stark erniedrigte Harnsäure und einen positiven Sulfittest im Urin. Welcher Defekt ist am wahrscheinlichsten?","a":"Molybdän-Cofaktor-Mangel mit Ausfall von Sulfit- und Xanthinoxidase","w":["Isolierter Sulfitoxidasemangel mit intakter Xanthinoxidase","Pyridoxinabhängige Epilepsie mit zerebralem PLP-Mangel durch ALDH7A1-Defekt","Biotinidasemangel mit multiplem Carboxylasemangel"],"why":"Nur der Moco-Mangel betrifft beide Enzyme (Sulfit ↑, Harnsäure ↓); beim isolierten Sulfitoxidasemangel ist die Harnsäure normal."},{"q":"Welcher Stoffwechselweg ist bei Molybdänmangel am direktesten betroffen?","a":"Abbau schwefelhaltiger Aminosäuren über Sulfit zu Sulfat","w":["Remethylierung von Homocystein zu Methionin","Oxidative Decarboxylierung von α-Ketosäuren","Carboxylierung von Propionyl-CoA zu Methylmalonyl-CoA"],"why":"Die Sulfitoxidase ist Moco-abhängig, Sulfit ist neurotoxisch; die Alternativen sind B12-, B1- bzw. biotinabhängig."},{"q":"Warum führt hohe Molybdänzufuhr bei Wiederkäuern, beim Menschen aber kaum zu Kupfermangel?","a":"Im sulfidreichen Pansen entsteht Thiomolybdat, das Kupfer bindet","w":["Wiederkäuer scheiden Kupfer über Molybdopterin vermehrt biliär aus","Molybdän hemmt beim Wiederkäuer direkt die Coeruloplasminsynthese","Wiederkäuer nehmen Molybdän über den Kupfertransporter CTR1 auf"],"why":"Molybdat und Sulfid bilden im Pansen Thiomolybdate; dieses Prinzip wird beim Menschen pharmakologisch (Tetrathiomolybdat) zur Kupferbindung genutzt."}]},{"id":"chrom","name":"Chrom","gruppe":"Spurenelemente","aktiveForm":"Dreiwertiges Chrom (Cr³⁺); eine definierte biologisch aktive Form ist nicht gesichert (das postulierte Chromodulin ist umstritten)","funktion":"Cr³⁺ wurde als Verstärker der Insulinwirkung beschrieben (Glukosetoleranzfaktor, Chromodulin-Modell), eine essenzielle Funktion ist jedoch nicht belegt. EFSA (2014) sah die Essenzialität nicht als gesichert an und hält keinen Referenzwert für angemessen, DGE/ÖGE nennen weiterhin einen Schätzwertbereich.","aufnahme":"Sehr geringe Absorption, durch Ascorbat und Aminosäuren gesteigert, durch Phytat und Antazida gemindert; Transport an Transferrin, Ausscheidung überwiegend renal. Sechswertiges Chrom (Cr⁶⁺) gelangt dagegen über Anionentransporter leicht in Zellen.","mangel":"Klinische Mangelzeichen sind nur aus Einzelfällen langfristiger parenteraler Ernährung ohne Chromzusatz bekannt: Glukoseintoleranz mit erhöhtem Insulinbedarf, Gewichtsverlust und periphere Neuropathie, die sich nach Chromgabe besserten.","risiko":"Klinisch nur bei langfristiger parenteraler Ernährung ohne Spurenelementzusatz diskutiert; für die Allgemeinbevölkerung ist kein Mangelrisiko belegt.","ueberdosis":"Cr³⁺ hat geringe Toxizität, EFSA hat mangels Daten keinen UL abgeleitet; Einzelfallberichte beschreiben Nieren- und Leberschäden unter Chrompicolinat. Cr⁶⁺ (berufliche Exposition) ist genotoxisch, karzinogen (Lungenkarzinom) und kontaktallergen.","quellen":"Fleisch, Eier, Haferflocken, Tomaten (DGE), Vollkorn, Nüsse; die Gehalte schwanken stark, auch durch Abrieb aus Edelstahlgeräten.","labor":"Kein verlässlicher Statusmarker: Serum- bzw. Plasmachrom liegt nahe der Nachweisgrenze und ist kontaminationsanfällig, Urinchrom spiegelt nur die aktuelle Zufuhr. Unter parenteraler Ernährung wird allenfalls das Ansprechen der Glukosetoleranz herangezogen.","interaktion":"Ascorbat steigert, Phytat und Antazida mindern die Absorption. Für Chromsupplemente bei Typ-2-Diabetes ist die Evidenz für klinisch relevante Effekte inkonsistent, obwohl in der EU eine gesundheitsbezogene Angabe zum Blutzucker zugelassen ist.","ref":{"wert":"30–100 µg/Tag (Jugendliche und Erwachsene, m und w)","art":"Schätzwert","quelle":"https://www.dge.de/wissenschaft/referenzwerte/kupfer-mangan-chrom-molybdaen/","stand":"2000"},"ul":null,"links":{"dis":["diabetes_typ2","kurzdarmsyndrom"],"path":[]},"mcq":[{"q":"Wie unterscheiden sich DGE/ÖGE und EFSA in der Bewertung von Chrom?","a":"DGE: Schätzwertbereich; EFSA: kein Referenzwert, Essenzialität unbelegt","w":["DGE: identische Schätzwerte wie EFSA; EFSA: zusätzlich ein UL für Cr³⁺-Salze","DGE: Cr³⁺ als toxisch eingestuft; EFSA: Empfehlung abgeleitet","DGE: Essenzialität verneint; EFSA: PRI aus Bilanzstudien"],"why":"EFSA (2014): Essenzialität von Cr³⁺ nicht belegt, weder AR/PRI noch AI angemessen; die DGE-Schätzwerte stammen aus dem Jahr 2000."},{"q":"Unter welcher Bedingung wurde beim Menschen ein Chrommangel mit klinischen Folgen beschrieben?","a":"Langzeit-PN ohne Chrom mit Hyperglykämie, erhöhtem Insulinbedarf und Neuropathie","w":["Vegane Ernährung mit sehr hoher Phytatzufuhr bei bereits bestehendem Typ-2-Diabetes","Hoher Zuckerkonsum mit stark gesteigerter renaler Chromausscheidung","Langjährige Metformintherapie mit gestörter intestinaler Chromaufnahme"],"why":"Die Fallberichte unter PN besserten sich nach Chromgabe; in der Allgemeinbevölkerung ist ein Mangel nicht belegt."},{"q":"Warum ist sechswertiges Chrom (Cr⁶⁺) wesentlich toxischer als dreiwertiges (Cr³⁺)?","a":"Chromat nutzt Anionentransporter und bildet bei intrazellulärer Reduktion DNA-Addukte","w":["Cr⁶⁺ wird deutlich stärker an Transferrin gebunden und in Knochenmark und Leber angereichert","Cr³⁺ wird im sauren Magen zu Cr⁶⁺ oxidiert und wirkt erst danach toxisch","Cr⁶⁺ hemmt kompetitiv den Insulinrezeptor und verursacht Hypoglykämien"],"why":"Chromat ähnelt Sulfat und Phosphat und nutzt deren Transporter; intrazellulär wird es über Cr⁵⁺/Cr⁴⁺ zu Cr³⁺ reduziert, das DNA-Addukte bildet, während Cr³⁺ selbst kaum membrangängig ist."}]}];
